-- Generated by QuestData/Tools/import_multilanguage_quests.py.
-- Known IDs only; Classic-source passages are compatibility fallbacks on Forever.
local source = "MultiLanguage Classic c51dc2e5141f070f5b92de190521d79e8dccaeab"
local data = WordHunterWoW_QuestDataByFlavor
local function apply(id, targets, passages)
    for _, flavor in ipairs(targets) do
        local languages = data and data[flavor]
        for locale, fields in pairs(passages) do
            local record = languages and languages[locale] and languages[locale][id]
            if record then
                for field, text in pairs(fields) do
                    if not record[field] or record[field] == "" then
                        record[field] = text
                        record[field .. "Source"] = source
                        record[field .. "SourceFlavor"] = "classic"
                    end
                end
            end
        end
    end
end

apply(562, { "classic", "forever" }, { deDE = { progress = "Ich hab einen Brief fertig für Major Samuelson in Stormwind. Ich brauche nur noch die Ergebnisse.", completion = "Jetzt wo die Naga hier in Southshore erledigt sind, bin ich so gut wie weg hier. Ich werde Stormwind wiedersehen... und aus diesem Licht-verlassenen Hafen wegkommen." }, enUS = { progress = "I've a letter ready to go to Major Samuelson in Stormwind. All I need are the results.", completion = "With the naga put down in Southshore, I'll be a shoe-in to be reassigned. I'll get to see Stormwind again... get away from this Light-forsaken port." } })
apply(563, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, Bürger. Kann die Stadtwache von Stormwind Euch behilflich sein?", completion = "Was ist das? Ah... da hat mein aufmerksamer Schüler sich wohl des Nagaproblems in Southshore angenommen. Ich danke Euch für das Überbringen, ich werde das auf jeden Fall berücksichtigen, wenn ich im nächsten Monat die Personalversetzungen überprüfe." }, enUS = { progress = "Greetings, citizen. May the Stormwind city guard be of assistance?", completion = "What's this? Ah... so my attentive pupil has applied himself to the problem of the naga in Southshore. Thank you for bringing this to me, I will certainly take it into account when I review personnel assignments in the next month." } })
apply(564, { "classic", "forever" }, { deDE = { completion = "Na das sin' ma' gute Neuichkeiten! Hätt' ich mir gleich 'n richtichen Kriechshelden ranholen soll'n, der sich um die Viecher kümmern tut. Euer Pappa wär ja so stolz auf Euch, {name}." }, enUS = { completion = "Ain't that great news!  Should-a gone and found me a regular ol' war hero from day one to take care of them beasts.  You'd-a made your pappy proud, {name}." } })
apply(565, { "classic", "forever" }, { deDE = { progress = "Ihr seid also zum großartigen Bartolo zurückgekehrt. Seid Ihr vielleicht schon fertig mit dem Sammeln der Dinge, die für Euren Yetifellumhang benötigt werden? Oder vielleicht möchtet Ihr Euch ein wenig an meiner Großartigkeit, der Großartigkeit des großen Bartolo sonnen!", completion = "Jetzt ist die Zeit für den großen Bartolo gekommen, seine Magie zu wirken! Ich brauche keinen Hexer-Stab und keine Magier-Rute! Denn ich, der große Bartolo, kann mit einer einfachen Nadel und Faden Magie wirken!" }, enUS = { progress = "So you have returned to the great Bartolo.  Perhaps you have finished gathering the materials needed for your Yeti Fur Cloak?  Or maybe you just enjoy basking in the greatness of me, Bartolo!", completion = "Now it is time for the great Bartolo to work his magic!  I require no wizard's staff, no mage's rod.  For I, the great Bartolo, work magic with a mere needle and thread!" } })
apply(566, { "classic", "forever" }, { deDE = { progress = "Ah, {name}. Seid Ihr vielleicht gekommen, um das Kopfgeld einzuholen, das auf den Kopf von Baron Vardus ausgesetzt wurde?", completion = "Ihr seid sehr produktiv, {name}. Mit dem Tod von Baron Vardus sinkt auch die Zahl der Syndikatsanführer. Ihr Widerstand wird nur noch ein kurzlebiges Ärgernis sein." }, enUS = { progress = "Ah, {name}. Perhaps you've come to collect the bounty on the head of Baron Vardus?", completion = "Productive work you do, {name}. With Baron Vardus dead, the number of Syndicate leaders grows smaller. Their resistance and irritation will be short-lived." } })
apply(567, { "classic", "forever" }, { deDE = { completion = "Ihr seid ein sehr geschickter Kopfgeldjäger, {class}. Gut gemacht." }, enUS = { completion = "You are quite the bounty hunter, {class}.  Well done." } })
apply(568, { "classic", "forever" }, { deDE = { completion = "Ihr habt Eure Pflicht ehrenhaft erfüllt, {class}." }, enUS = { completion = "Your duty was performed with honor, {class}." } })
apply(569, { "classic", "forever" }, { deDE = { completion = "Gut gemacht. Ihr habt dem Kriegshäuptling ehrenhaft gedient." }, enUS = { completion = "Well done.  You have served the Warchief with honor." } })
apply(570, { "classic", "forever" }, { deDE = { progress = "Was für Neuigkeiten bringt Ihr mir?", completion = "Ihr habt eine sehr gute Kenntnis des Dschungels, {name}. Diese Exemplare eignen sich perfekt. Ich werde den Geistern dafür danken, dass sie diese edlen Kreaturen für die Sache der Horde geopfert haben." }, enUS = { progress = "What news do you bring?", completion = "Your knowledge of the jungle is strong, {name}.  These specimens will be perfect.  I will thank the spirits for sacrificing such fine beasts for the cause of the Horde." } })
apply(571, { "classic", "forever" }, { deDE = { progress = "War das Glück auf Eurer Seite, {name}? Konntet Ihr die Sehne eines alten Gorillas bekommen, {name}?", completion = "Eine wirklich ideale Sehne, {name}. Eure Bemühungen werden sich bald bezahlt machen." }, enUS = { progress = "Has fortune been on your side, {name}?  Were you able to obtain an aged gorilla sinew?", completion = "A most ideal sinew, {name}.  Your efforts will pay off soon." } })
apply(572, { "classic", "forever" }, { deDE = { progress = "Sind Eure Bemühungen von Erfolg gekrönt?", completion = "Vorzüglich. Ich werde sie sofort vorbereiten." }, enUS = { progress = "Did your gathering efforts prove fruitful?", completion = "Most excellent.  I will prepare these at once." } })
apply(573, { "classic", "forever" }, { deDE = { progress = "Ich bin fast so weit, die Verzauberung abzuschließen. Habt Ihr meinen Auftrag erfüllt?", completion = "Mit diesem heiligen Quellwasser ist der zeremonielle Halsschmuck bereit zur Verzauberung.\n\nTragt ihn mit Stolz, {name}, im Namen des Kriegshäuptlings und zur Verteidigung der mächtigen Horde." }, enUS = { progress = "I am almost ready to complete the enchantment.  Have you performed my bidding?", completion = "With this Holy Spring Water the ceremonial choker is ready for enchantment.\n\nWear this with pride, {name}, in the name of the Warchief and in defense of the mighty Horde." } })
apply(574, { "classic", "forever" }, { deDE = { progress = "Sergeant Yohwa sagte mir, dass Ihr geschickt und mutig seid, {class}. Habt Ihr etwas zu berichten?", completion = "{name}. Sergeant Yohwa vertraute Euren Fähigkeiten, und ich vertraue ihr. Die Niederlage, die Ihr Kurzens Streitkräften beigebracht habt, ist fast mehr als wir zu hoffen wagten. Ich hatte befürchtet, dass wir Rebellen allein stünden, und allein hätten wir es nie mit der Genialität des Colonels aufnehmen können.\n\nVielleicht können wir immer noch auf unser Überleben hoffen." }, enUS = { progress = "Sergeant Yohwa tells me you are skilled and brave, {class}.  Do you have something to report?", completion = "{name}.  Sergeant Yohwa trusted your abilities, and I trust her.  The defeat you brought to Kurzen's forces is almost too much to hope for.  I had feared we rebels were alone, and alone we could never stand up against the Colonel's brilliance.\n\nPerhaps hope of our survival yet remains." } })
apply(575, { "classic", "forever" }, { deDE = { progress = "Meine Ausrüstung ist startklar, {name}, ich warte nur noch auf die Häute. Wir wollen Riddlevox ja nicht warten lassen.\n\nEs ist für niemanden gut, wenn der Cheferfinder des Tüftlerverbands unzufrieden ist.", completion = "Diese Häute sollen genügen. Ihre Qualität ist nicht allzu wichtig, da sie ja nur die innere Schicht der Stiefel bilden, aber sie sollten schon bequem sein.\n\nWenn sie ein bisschen zu steif sind, verwende ich ein wenig Tigerblut, um sie aufzuweichen. Kleines Betriebsgeheimnis, wisst Ihr?" }, enUS = { progress = "My equipment is all ready to go, {name}, I just need those skins. We don't want to keep Riddlevox waiting, that's for sure.\n\nIt's not a good idea for anyone to keep the chief inventor of the Tinkers' Union unsatisfied.", completion = "These skins should do. Their quality isn't too important, given that they'll make up the inside layer of the boots, but it's still important that they're comfortable.\n\nIf they're a bit too rigid, I'll use some tiger blood to soften it up. Tricks o' the trade, you know?" } })
apply(576, { "classic", "forever" }, { deDE = { progress = "Ahoi, Kumpel! Kann zwar nich' sehen, aber kann Euch schon über'n halben Hafen hinwech riechen.\n\nKönnte mein Auge wirklich gut gebrauchen. D'r Käpt'n wird mich wohl kielholen, wenn er rausfindet, dass mein Glubscher in die Hände der dreckigen Blutsegelbukaniere gefallen is'.\n\nWozu is'n Ausguck gut, wenn er nix sieht? Das Krähennest war mein Zuhause... ohne meine Augen kann ich von Glück sagen, wenn ich die Bilge schrubbn darf.", completion = "Da brat mir doch einer 'nen Storch! Ihr habt mein wunderbares Auge gefunden! Lass uns mal gucken, ob's noch passt.\n\n{name} ho! Kinners, ich kann sehen!!" }, enUS = { progress = "Ahoy, me bucko!  Might not be able to see but I can smell ye from halfway across port.\n\nCould really use me eye back.  Captain's going to keelhaul me when he finds out me peeper is in the hands of them dirty Bloodsail Buccaneers.\n\nWhat good is a lookout who can't see?  The crow's nest used to be me home...without me deadlights I'd be lucky to scrub the bilge.", completion = "Shiver me timbers and timber me shivers!  Ye found me beautiful eye!  Let's see if she still fits.\n\n{name} ho!  Blimey, I can see!!" } })
apply(577, { "classic", "forever" }, { deDE = { progress = "Drizzliks Exzelsiorlederstiefel, feinste Handwerksarbeit, Stiefel aus 100 Prozent Salzwasserkrokiliskenhaut von höchster Qualität. Es gibt nichts Besseres!\n\nSo eine tolle Beschreibung sucht ihresgleichen, was?\n\nOder habt Ihr vielleicht schon diese Häute für mich?", completion = "Meine Stiefel... sie sind 'n bisschen wie Würstchen, {name}. Sehen gut aus und schmecken auch so. Ich sag Euch, dass sie mit dem allerbesten Fleisch und feinsten Zutaten gefüllt sind und Ihr esst sie und Ihr liebt sie.\n\nEs ist sicherer - und schmackhafter -, wenn Ihr mir einfach nur traut und nicht allzu viele Fragen stellt, was wirklich drin ist." }, enUS = { progress = "Drizzlik's Excelsior leather boots, finest workmanship, one-hundred percent high quality saltwater crocolisk skin boots. None finer!\n\nCan't beat a glowing description like that, can you?\n\nExcept, maybe, if you have those skins for me?", completion = "My boots... they're like sausages, {name}. Look great, taste great. I tell you they're filled with nothing but the finest ingredients and meats, and you eat it, and you love it.\n\nIt's safer--and more enjoyable--if you just trust me, and don't ask too carefully what's really inside." } })
apply(578, { "classic", "forever" }, { deDE = { completion = "Also waren die Geschichten wirklich wahr! Unglaublich!\n\nAllerdings werden wir uns einen Weg überlegen müssen, wie wir den Fluch des Steins der Gezeiten besiegen können, sollten wir ihn bergen können. Der Fluch ist was für Magiebewanderte, also muss einer dieser Hexer uns behilflich sein." }, enUS = { completion = "So the stories were true! Incredible!\n\nHowever, we will need to figure out a way to defeat the curse of the Stone of the Tides, if we are to retrieve it. The curse is magical business, we'll need one of those wizards to help us out." } })
apply(580, { "classic", "forever" }, { deDE = { progress = "So ein Mist! Ich hab schon fast nix mehr zum Saufen da! Der Käpt'n wird bald Anker werfen und Ol' Slim is' trocken wie die Tanariswüste. Und wenn er dann merkt, dass sein Portwein verschwunden is'... Schietkram!", completion = "Nee, isses denn wahr! Ihr habt den Grog vom Käpt'n gefunden!\n\nIch schuld' Euch was, aber wirklich!\n\nSieht aus, als würd' sich ein Sturm zusammenbrau'n da draußen. Vielleicht mach ich's mir einfach hier drin mit einer der Flaschen gemütlich und warte, bis er vorbeigezogen is ..." }, enUS = { progress = "Sink me!  I'm almost outta booze here!  Cap'n is goin' to weigh anchor and Ol' Slim will be caught dry as the Tanaris Desert.  And once he discovers his port is missing. . . blimey!", completion = "Shiver me timbers!  Ye found the Cap'n's grog!\n\nI owe ye big time, friend.\n\nSeems like a storm is a brewin' outside.  Maybe I'll just keep warm with one o' these here bottles while we wait for it to pass...." } })
apply(581, { "classic", "forever" }, { deDE = { progress = "{class}. Zeigt mir, dass Ihr Beute von dem Bloodscalpstamm gemacht habt.\n\nZeigt mir Eure Trophäen.", completion = "Das sind gute Hauer, {name}. Ihr habt bewiesen, dass Ihr stark genug seid, um die Bloodscalps zu jagen.\n\nDas ist gut, denn die Jagd auf sie ist für Euch noch nicht vorbei." }, enUS = { progress = "{class}.  Show me you have made prey of the Bloodscalp tribe.\n\nShow me your trophies.", completion = "These are good tusks, {name}.  You prove that you have the strength to hunt the Bloodscalps.\n\nAnd that is good, because you are not done hunting them." } })
apply(582, { "classic", "forever" }, { deDE = { progress = "{name}. Ich fürchte um den Sohn unseres Häuptlings. Habt Ihr die Schrumpfköpfe, sodass ich sie untersuchen kann?", completion = "Ich danke Euch, {name}. Ich werde sie sogleich untersuchen, um sicherzugehen, dass der arme Yenniku der Axt der Kopfjäger entgangen ist." }, enUS = { progress = "{name}.  I fear for our chief's son.  Do you have the shrunken heads so I may inspect them?", completion = "Thank you, {name}.  I will inspect these heads to ensure poor Yenniku was spared the headhunter's axe." } })
apply(583, { "classic", "forever" }, { deDE = { completion = "Sehr erfreut Eure Bekanntschaft zu machen, {name}. Hab hier in der Gegend schon lange keinen Eurer Sorte mehr gesehen, {class}.\n\nIch habe mich nur aus einem Grund auf diese Expedition begeben: Ich will eine große und scheue Bestie jagen. Da ich erkennen kann, dass Ihr eine Art Held seid, bin ich willens, Euch an der Jagd zu beteiligen. Ihr müsst Euch zunächst jedoch beweisen.\n\nIch werde Euch lehren, wie man Raptoren tötet. Ajeck wird Euch mit der Tigerjagd vertraut machen. Und Sire Erlgadin ist ein Meister, wenn es um das Aufspüren eines Panthers geht.\n\nBeweist mir Eure Geschicklichkeit und Ihr dürft mit auf die große Jagd." }, enUS = { completion = "Jolly nice to make your acquaintance, {name}. Haven't seen a {class} around these parts for some time.\n\nI situated myself with this expedition for one purpose: to hunt a great and elusive beast. Seeing that you're a hero of sorts I am willing to let you take part in the hunt, but you must first prove yourself.\n\nI shall teach the ways of raptor killing to you. Ajeck will train you with tiger hunting. And Sir Erlgadin is a master of panther tracking.\n\nProve your skill and I'll let you in on the big hunt." } })
apply(584, { "classic", "forever" }, { deDE = { progress = "Die grünliche Brühe im Kessel blubbert.", completion = "Ihr legt die Köpfe von Gan'zulah und Nezzliok in den Kessel..." }, enUS = { progress = "The greenish broth within the cauldron bubbles.", completion = "You place the heads of Gan'zulah and Nezzliok within the cauldron..." } })
apply(585, { "classic", "forever" }, { deDE = { progress = "Ich erwarte die Schädel...", completion = "Ja. Diese werden mir gute Dienste leisten. Wenn mein Geist befreit wurde, werde ich mit drei guten Dienern in das Nether eintreten!\n\nIhr seid eine Zierde Eures Klans, {race}, und Ihr habt mich beschwichtigt." }, enUS = { progress = "I await the skulls...", completion = "Yes.  These will serve me well.  When my spirit is freed, I will enter the Nether with three fine servants!\n\nYou are a credit to your {race} clan, and you have appeased me." } })
apply(586, { "classic", "forever" }, { deDE = { progress = "Obwohl mein eigenes Fleisch von meinem Schädel fällt, kann ich Eure Furcht immer noch riechen.\n\nHa! Ihr werdet meine Aufgabe niemals erfüllen...", completion = "Ich will es nicht glauben, aber ich kann Eure Tat nicht verleugnen. Und meine Wut lässt nach, nun, da Ana'thek besiegt ist. \n\nEure Macht wird Euch zu großen Taten treiben, {name}. Aber eines Tages... werde ich Euch im Nether wiedersehen und wir werden erneut unsere Kräfte messen.\n\nIch werde Euch erwarten." }, enUS = { progress = "Although my own flesh boils off my skull, I can still smell your fear.\n\nHah!  You will never complete my task...", completion = "I do not want to believe it, but I cannot deny what you have done.  And my rage eases, now that Ana'thek is defeated.  \n\nYour might will drive you to great deeds, {name}.  But one day...I will see you in the Nether and we will again match strength.\n\nI will be waiting." } })
apply(587, { "classic", "forever" }, { deDE = { progress = "Glück mit den Waren, Kumpel?", completion = "Klasse gemacht, {name}! Und gerade noch rechtzeitig, bevor ich wieder Anker lichten muss! Kann Euch gar nicht genug danken, alter Freund." }, enUS = { progress = "Any luck finding the goods, matey?", completion = "Good show, {name}!  And just before I need to ship out too!  Can't thank you enough, old friend." } })
apply(588, { "classic", "forever" }, { deDE = { completion = "Zanzil der Ausgestoßene??\n\nWenn Yenniku von diesem Troll festgehalten wird, einem bösartigen und mächtigen Hexendoktor, dann fürchte ich, dass nur ein kleines bisschen Hoffnung bleibt. Eine schwache Hoffnung. Ungefähr so groß wie ein winziges Insekt.\n\nAber es ist immer noch eine Hoffnung." }, enUS = { completion = "Zanzil the Outcast??\n\nIf Yenniku is held by that troll, a vile and powerful witchdoctor, then I fear that only a faint hope remains.  Faint.  And tiny as the smallest insect.\n\nBut still, it is hope." } })
apply(589, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Splitter, {name}? Ich brauche sie für mein letztes Ritual, nachdem wir das Gedankenauge erhalten haben.", completion = "Ihr habt Eure Sache gut gemacht, {name}. Diese Splitter haben eine gute Form. Ich kann bereits hören, wie sie zu mir singen.\n\nUnd während Ihr fort wart, sprach ich mit den Geistern des Dschungels. Ich weiß, wo sich das Gedankenauge befindet...\n\n... und auch, wer es bewacht." }, enUS = { progress = "Do you have the shards, {name}?  They are needed for my final ritual, after we have the Mind's Eye.", completion = "You have done well, {name}.  These shards are well formed.  Already I hear them sing to me.\n\nAnd while you were gone, I spoke with the spirits of the jungle.  I know where the Mind's Eye rests...\n\n...And who guards it." } })
apply(590, { "classic", "forever" }, { deDE = { completion = "Unglaublich! Was für ein Talent!\n\nIch dachte, Ihr wärt eine leichte Beute, {name}. Habt mich gut geschlagen.\n\nHier das Geld, das ich versprochen habe... nicht so viel, wie ich eigentlich sagte. Das kommt daher, dass ich damals schon gelogen hab." }, enUS = { completion = "Incredible! What skill!\n\nThought you'd be easy prey, {name}. Got me good, you did.\n\nHere's the coin I promised... not as much as I said it'd be, but that's on a count o' me lying to ya in the first place." } })
apply(591, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, {name}. Die Geister lobpreisen Euren Mut, aber sie sagen mir nichts von Eurem Kampf gegen Mai'Zoth.\n\nHabt Ihr das Auge?", completion = "Ihr habt das Auge bekommen! Eure Macht hat das Zeug zur Legende, {name}!\n\nUnd da Ihr im Besitz des Auges seid, müsst Ihr Mai'Zoth besiegt und ihn ins Nether geschickt haben. Darum wollten die Geister zuvor nicht von ihm sprechen.\n\nEs ist gut, dass er diese Welt des Fleisches und der Knochen verlassen hat, aber nun, da er im Reich der Geister wandelt... fürchte ich, wird er dort erneut die Macht ergreifen.\n\nAber darum sorge ich mich ein anderes Mal. Jetzt muss ich erst ein Ritual durchführen, um uns das Gedankenauge zu Willen zu machen..." }, enUS = { progress = "Greetings, {name}.  The spirits sing praise of your bravery, yet they tell me no tales of your quest against Mai'Zoth.\n\nDo you have the Eye?", completion = "You retrieved the eye!  Your might is the stuff of legends, {name}!\n\nAnd in getting the Eye, you must have defeated Mai'Zoth and sent him to the Nether.  That is why the spirits would not mention him before.\n\nIt is good that he is gone from the world of flesh and bone, but now that he is in the realm of spirits...I fear he will begin a new reign.\n\nBut that is a worry for another time.  Now, I must perform a ritual to bend the Mind's Eye to our needs..." } })
apply(592, { "classic", "forever" }, { deDE = { progress = "{name}. Kin'weelay sagte mir, er habe Euch ausgesandt, Yenniku zu finden.\n\nIst es wahr? Habt Ihr ihn?", completion = "Ihr habt es geschafft! Ihr konntet Yenniku vom Willen Zanzils trennen und so die Mission erfüllen, die ich kurz vorm Scheitern sah.\n\nUnser Stamm wird Euren Namen in Liedern ehren, {name}, und wir werden Eure Geschichte in Stein ritzen, so dass sie auf ewig leben wird." }, enUS = { progress = "{name}.  Kin'weelay told me you set out to capture Yenniku.\n\nIs it true?  Do you have him?", completion = "You've done it!  You freed Yenniku from the will of Zanzil, and completed the mission I had thought was so desperate.\n\nOur tribe will remember your name in songs, {name}, and we will etch your tale in stone so that it will live forever." } })
apply(594, { "classic", "forever" }, { deDE = { completion = "Seid Ihr gekommen, mich zu befreien?" }, enUS = { completion = "Have you come to free me?" } })
apply(595, { "classic", "forever" }, { deDE = { completion = "Oben auf dem Fass findet Ihr eine Karte mit einigen hastig geschriebenen Worten und einigen Münzen." }, enUS = { completion = "On top of the barrel, you discover a map with some hastily written text on it along with some coins." } })
apply(596, { "classic", "forever" }, { deDE = { progress = "Eines Tages werden die Bloodscalps von den Darkspears zertreten werden! Habt Ihr die Halsketten unseres verdammten Feindes?", completion = "Ah, sehr gut. Ich werde sie kochen und absaugen und der Geist ihrer Besitzer wird immer schwächer werden, während ich ihre Halsketten zu Brei zermalme!\n\nHier, {name}. Dies begleicht meine Schuld bei Euch." }, enUS = { progress = "The Bloodscalps will one day be crushed by the Darkspears!  Do you have the necklaces of our doomed foe?", completion = "Ah, very good.  I will boil these, and leech them, and the spirits of their owners will weaken as I render their necklaces to paste!\n\nHere, {name}.  This will repay my debt to you." } })
apply(597, { "classic", "forever" }, { deDE = { completion = "Natürlich erinnere ich mich an Euch, {class}. Zurück vom Ausspähen, wie ich sehe..." }, enUS = { completion = "Sure, I remember you, {class}.  Back from scouting I see...." } })
apply(598, { "classic", "forever" }, { deDE = { progress = "Die Skullsplitter werden den Tag verdammen, an dem sie uns den Krieg erklärten! Ist Eure Aufgabe erfüllt?", completion = "Eure Stärke muss groß sein, dass Ihr diese Halsketten erringen konntet, {name}. Ihr vernichtet die Skullsplitter wie ein Basilisk, der junge Schösslinge in den Boden tritt!\n\nEure Taten sind uns ein Segen." }, enUS = { progress = "The Skullsplitters will curse the day they brought us to war!  Is your task complete?", completion = "Your strength is great to have gained these necklaces, {name}.  The Skullsplitters fall to you like young saplings stomped to earth by a Basilisk!\n\nYour deeds are a boon to us." } })
apply(599, { "classic", "forever" }, { deDE = { completion = "Blutsegelbukaniere wollen Booty Bay angreifen? Da können sie sich doch gleich die Aussichtsklippen runterstürzen. Aber egal, Ihr habt meiner Flotte von Schwadroneuren einen großen Dienst erwiesen, indem Ihr mir diese Information zugetragen habt. Die Schwarzmeerräuber danken Euch." }, enUS = { completion = "Bloodsail Buccaneers attacking Booty Bay?  They might as well throw themselves off the Overlook Cliffs.  Nonetheless, by bringing me this information you have done my fleet of swashbucklers a great service.  The Blackwater Raiders thank you." } })
apply(600, { "classic", "forever" }, { deDE = { progress = "Habt Ihr diese Kristalle?? Ich brauche sie!!\n\nIch meine... ich brauche Gewissheit, dass die böse Venture Company im Schlingendorntal an Boden verliert. Weil, wisst Ihr, wir ehrlichen Leute müssen auch leben!", completion = "Großartig! Wunderbar! Dafür krieg ich einen Haufen!\n\nDie Venture Company hat sich den falschen Dschungel für die Minen ausgesucht, nicht wahr? Es würde uns allen besser gehen, wenn sie hier verschwänden.\n\nIch danke Euch, {name}. Ihr habt heute eine gute Tat getan." }, enUS = { progress = "Do you have those crystals??  I need them!!\n\nI mean...I need to know the evil Venture Company is losing ground in Stranglethorn.  Because, you know, we honest folk have to make a living!", completion = "Great!  Wonderful!  I can get a bundle for these!!\n\nThat Venture Company sure picked the wrong jungle to mine in, didn't they?  We'd all be in better shape if they moved out of here.\n\nThank you, {name}.  You've done a good deed this day." } })
apply(601, { "classic", "forever" }, { deDE = { progress = "Hattet Ihr Glück, {name}?", completion = "Hmm, ich bin nicht geeignet, diese Armschienen zu untersuchen, um zu sehen, ob sie von Nutzen sind, aber ich bin sicher, dass zumindest ein Teil uns nützlich sein wird. Bringt sie nach Dalaran und lasst einen Magier einen Blick darauf werfen.\n\nSchließlich kann ich Booty Bay nicht einfach so verlassen, nur um mit einem dieser nervigen alten Magier ein Schwätzchen zu halten.\n\nNicht, dass ich mir Sorgen machte, irgendjemand könnte sich in der Zwischenzeit zum neuen Baron machen. Wer Revilgaz verärgert, lebt nicht mehr lang genug, um davon zu erzählen." }, enUS = { progress = "Have you had any luck, {name}?", completion = "Hm, I haven't the eye to examine these bracers to see if any of them will be of any use, but I'm sure at least one of them will be able to help. Take them to Dalaran and have a mage look at them.\n\nAfter all, I can't very well leave Booty Bay just to chat with those tiresome old mages.\n\nNot that I'm worried anyone would try to elbow their way into being the new baron. No one crosses Revilgaz and lives to tell of it." } })
apply(602, { "classic", "forever" }, { deDE = { progress = "Wenn Ihr mich entschuldigt, ich bin im Moment sehr beschäftigt.", completion = "Der Stein der Gezeiten? Äußerst interessant. Es mag Euch überraschen zu erfahren, dass ich vor vielen Jahren einen Folianten geschrieben habe, der sich mit den Legenden des Reiches der Gurubashi beschäftigt. Ich weiß einiges über den Stein.\n\nZumindest an einer dieser Armschienen scheinen ein wenig magische Überreste zu haften, die ich analysieren kann.\n\nDann lasst uns mal sehen, was ich so sehen kann..." }, enUS = { progress = "If you wouldn't mind, I am rather busy right now.", completion = "The Stone of the Tides? Most interesting. It might surprise you to know that I wrote a tome--several years ago--pertaining to the legends of the Gurubashi Empire. I do know quite a bit about the Stone.\n\nAt least one of these bracers appears to have some magical residue I can analyze.\n\nLet's see what I can see..." } })
apply(603, { "classic", "forever" }, { deDE = { completion = "Mein Dolch? Was seid Ihr denn für ein Komiker?\n\nWas? Soll ich Euch die ganze Geschichte noch einmal erzählen, wie ich vom besten Messerkämpfer in Booty Bay zur Witzfigur der ganzen Piratenschaft wurde?\n\nIch habe einen Messerkampf gegen einen dieser Blutsegelbukaniere verloren - eine echte Bande von Bastarden! -, und er nahm meine Klinge als Beute.\n\nAls könnte ich nur mit Beleidigungen und meiner scharfen Zunge ausgestattet, noch irgendwas bei Messerkämpfen werden." }, enUS = { completion = "My dagger? What are you, some sort of comedian?\n\nWhat? Do you just want me to repeat the story of how I've gone from the best knife fighter in Booty Bay to the laughing stock of piratedom!\n\nI lost a knife fight to one of the Bloodsail Buccaneers--bunch of right bastards they are!--and he took my blade as spoils.\n\nIt's not as though I can get by as a knife fighter with insults and a sharp tongue alone..." } })
apply(604, { "classic", "forever" }, { deDE = { progress = "Ahoi, {name}. Welche Neuigkeiten bringt Ihr aus dem Lager der Blutsegelbukaniere im Süden?", completion = "Perfekt, {name}. Jetzt, da wir ihren Plan kennen, ist das Ganze nur noch eine Frage der Zeit.\n\nUnd wenn ich nur dran denke, dass diese Trottel ganz in der Nähe des Capes vor Anker gegangen sind..." }, enUS = { progress = "Ahoy, {name}.  What word do you bring of the Bloodsail encampment to the south?", completion = "Perfect, {name}.  Now that we know their plan, it's just a matter of time.\n\nAnd to think the fools have dropped anchor just off the cape...." } })
apply(605, { "classic", "forever" }, { deDE = { completion = "Aha! Diese eignen sich wunderbar, {name}. Und wie wunderbar!\n\nHier ist Euer Anteil, und... es war mir eine Freude, mit Euch Geschäfte zu machen." }, enUS = { completion = "Aha!  These will do nicely, {name}.  Yes, quite nicely!\n\nHere is your cut, and...it was a pleasure doing business with you." } })
apply(606, { "classic", "forever" }, { deDE = { progress = "He! Den Blick, den Ihr mir da zuwerft, mag ich gar nicht, Sire.", completion = "Igitt! Wo habt Ihr das denn her? Nein, sagt es mir lieber nicht. Ich will es gar nicht wissen!\n\nWer hat Euch geschickt? Seewolf?" }, enUS = { progress = "Hey!  I don't like the look you're giving me, mister.", completion = "Ack!  Where'd you get these?  No, don't tell me. I don't want to know!\n\nWho sent you?  Sea Wolf?" } })
apply(607, { "classic", "forever" }, { deDE = { progress = "Hallo hallo, {name}. Habt Ihr Zitterhands Bezahlung bekommen?", completion = "He he, gut gemacht. Und als Ihr Zitterhand die Innereien gezeigt habt, wie stark hat er da gezittert?\n\nHa! Er ist so leicht zu durchschauen. Wenn ich mit ihm Karten spiele, kann ich einfach nur gewinnen!\n\nIch danke Euch für Eure Hilfe, {name}. Nun ist es Zeit, dass Ihr Eure Bezahlung erhaltet..." }, enUS = { progress = "Here here, {name}.  Did you get Shaky's payment?", completion = "Heh heh, well done!  And when you showed Shaky those giblets, how hard did he shake?\n\nHah!  He's so easy to read, when I play cards with him I can't help but win!\n\nThanks for your help, {name}.  Now it's your turn to get paid..." } })
apply(608, { "classic", "forever" }, { deDE = { progress = "Wo liegt das Problem, {name}? Wir müssen angreifen bevor die Blutsegelbukaniere es tun!", completion = "Ah, was für ein wunderbarer Tag für die Schwarzmeerräuber! Ein dreifaches Hurra für Euch, {name}!" }, enUS = { progress = "What's the problem, {name}?  We need to attack before the Bloodsail Buccaneers do!", completion = "Ah, what a great day for the Blackwater Raiders!  Three cheers to you, {name}!" } })
apply(609, { "classic", "forever" }, { deDE = { progress = "{name}, habt Ihr diese drei Hunde gefunden? Habt Ihr ihre Wertsachen eingesammelt?", completion = "Großartig! Dafür krieg ich einen guten Preis, ganz besonders für das, was sich in Maurys Fuß befindet! Vielen Dank, {name}!\n\nHoffentlich haben die drei ihre Lektion gelernt: Wettet nicht auf was, das Ihr Euch nicht leisten könnt, zu verlieren.\n\nVielleicht ist es für sie ja schon zu spät, aber... sie sollten vorsichtig bei der Wahl sein, mit wem sie spielen." }, enUS = { progress = "{name}, did you find those three dogs?  Did you collect their valuables?", completion = "Great!  I can get a good price for these, especially for what's inside Maury's foot!  Thanks much, {name}!\n\nI hope those three learned their lesson: don't bet something you can't afford to lose.\n\nAnd maybe it's too late for them, but...they should be careful of who they gamble with." } })
apply(610, { "classic", "forever" }, { deDE = { progress = "Ich bin noch nie besiegt worden, wisst Ihr, {name}? Natürlich hab ich ein paar Schnitte abgekriegt, kein Messerkampf ohne so was, aber er hat mir einfach an den Kopf gehauen und weg war ich. Als ich wieder zu mir kam, war meine Klinge weg.\n\nObwohl mein Spitzname es anders vermuten lässt, brauche ich dennoch ein Messer zum kämpfen, und für mich muss es einfach dieses sein.", completion = "Ihr habt Duncan geschlagen? Scheint, als wärt Ihr nicht ganz so grün hinter den Ohren, wie Ihr es bei einem ersten Blick vermuten lasst.\n\nIch denke mal, dass es auch bedeutet, dass ich Euch in der nächsten Zeit besser nicht zu einem Kampf herausfordern sollte!" }, enUS = { progress = "I'd never been beat before, you know, {name}? Sure I'd been cut, can't get in a knife fight without that, but he just smacked me on the side of the head, blacked me out. When I came to my blade was gone.\n\nAs much as my nickname might indicate, I still need a knife to fight, and for me, it has to be that one.", completion = "You beat Duncan? I guess you aren't as wet behind the ears as you looked at first glance.\n\nI suppose that also means I shouldn't challenge you to a fight any time soon!" } })
apply(611, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Stein der Gezeiten für mich mitgebracht, {name}? Ich habe schon ein wenig Platz gemacht und einen schönen Aufsteller dafür besorgt.", completion = "Erstaunlich! Der Stein der Gezeiten! Er wird einen ganz besonderen Platz in meiner Sammlung alter Troll-Artefakte erhalten. Habt Ihr gesehen, dass es fast so aussieht, als seien die Gezeiten unter seiner Oberfläche gefangen? Wie wundersam!" }, enUS = { progress = "Have you retrieved the Stone of the Tides for me, {name}? I've already cleared out a space and purchased a fine stand for it.", completion = "Amazing! The Stone of Tides! It shall have a place of prominence in my collection of ancient troll artifacts. Did you see how it almost seems as though a tide is trapped within its surface? Magnificent!" } })
apply(613, { "classic", "forever" }, { deDE = { progress = "Ahoi, {name}! Habt Ihr Maurys Schlüssel schon gefunden?", completion = "Ihr habt ihn gefunden! Vielen vielen Dank, {name}. Ihr wart mir eine große Hilfe!\n\nHier, nehmt das, Ihr habt es Euch verdient!" }, enUS = { progress = "Ahoy, {name}!  Have you yet found Maury's Key?", completion = "You found it!  Thanks a million, {name}.  You've been a big help to me!\n\nHere you go - you earned this!" } })
apply(616, { "classic", "forever" }, { deDE = { completion = "Interessant. Ich meine, vor einiger Zeit ein Buch gelesen zu haben, das nahe legte...\n\nAh, ja natürlich, es war eine Trolllegende. Wenn das, was Krazek berichtet, wahr sein sollte, dann werde ich vielleicht bald den Stein der Gezeiten meiner Sammlung von alten Artefakten und Relikten hinzufügen können." }, enUS = { completion = "Interesting. Some time ago, I seem to remember reading a book once that suggested...\n\nAh, of course, a troll legend it was. If what Krazek reports is true, perhaps I will soon be able to add the Stone of the Tides to my collection of ancient artifacts and relics." } })
apply(617, { "classic", "forever" }, { deDE = { progress = "Wenn 'er mit mir keine Geschäfte machen wollt, dann verschwindet, {name}.", completion = "Gut gemacht, {name}. 10 Stängel Akirisschilfrohr waren wohl keine Herausforderung für Euch, oder? Nix gegen die Naga, aber es muss ja jeder schließlich sehen, wie er zurechtkommt." }, enUS = { progress = "If ya got no business with me, then move along, {name}.", completion = "Well done, {name}. 10 stalks of akiris reed wasn't too much a challenge after all, huh? No offense to the naga, but hey, everybody's gotta make a living." } })
apply(621, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Proben von Zanzils Mixtur??", completion = "Ah, sehr gut! Hier ist Eure Bezahlung.\n\nUnd hier noch ein kleiner Zuschuss... für Eure Verschwiegenheit." }, enUS = { progress = "Do you have the samples of Zanzil's Mixture??", completion = "Ah, very good!  Here is your pay.\n\nAnd here is a little something extra... for your discretion." } })
apply(622, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Seid Ihr bis Booty Bay gekommen? Hat der Goblin Krazek meinen Topf repariert??", completion = "Er ist wieder heile! Das ist toll, jetzt kann ich endlich mit dem Abendessen anfangen! Ich danke Euch vielmals, {name}.\n\nIch hoffe, es erging Euch gut in Booty Bay. Dort kann es ganz schön rau hergehen, und... ich habe Gerüchte gehört, dass die Goblins manchmal betrunkene Seeleute in ihre Sklavenboote zerren...\n\n... wo sie gezwungen werden, wer weiß wo hinzusegeln und wer weiß was zu tun..." }, enUS = { progress = "Hello, {name}.  Did you make it to Booty Bay?  Did the goblin Krazek fix my pot??", completion = "It's fixed!  This is great, now I can get dinner started!  Thanks so much, {name}.\n\nI hope you were okay in Booty Bay.  That place can get pretty rough, and... I heard rumors that the goblins will sometimes drag drunk sailors to their slave boats and take them to who-knows-where... to do who-knows-what..." } })
apply(623, { "classic", "forever" }, { deDE = { progress = "Waas?", completion = "Was?! Ich habe Besseres zu tun, als mit Euresgleichen zu reden, {class}. Entweder es springt was für mich raus, oder Ihr verschwindet aus meinem Gesichtskreis.\n\nHä? Bloads hat Euch geschickt, hm? Nun, was habt'er denn für mich?\n\n\n\nNicht schlecht, gar nicht mal so schlecht. Ein weiteres Bündel wird meinen Kunden sehr glücklich machen.\n\nIch nehme an, Eure nächste Frage ist die nach dem Geld, nich, {class}? Kann ja gar nich' anders!\n\nHier, nehmt diese Münzen und noch'n Ratschlag: Runter von meinen Docks." }, enUS = { progress = "Yeah?", completion = "What?! I got a lot better things to do then talk to the likes of you, {class}. Make it worth my while or get outta my face.\n\nHuh? Bloads sent ya, huh? Well, whaddaya got for me?\n\n\n\nNot bad, not bad at all. Another bundle will make my client quite happy.\n\nI suppose yer next question's gonna be about money, huh, {class}? Of course it is!\n\nHere, take this coin and some advice: get off my docks." } })
apply(624, { "classic", "forever" }, { deDE = { completion = "Das durchnässte Pergament enthält den nächsten Hinweis..." }, enUS = { completion = "The soggy parchment contains the next clue...." } })
apply(625, { "classic", "forever" }, { deDE = { completion = "Ihr findet eine modrige Rolle." }, enUS = { completion = "You find a musty scroll." } })
apply(626, { "classic", "forever" }, { deDE = { completion = "Ihr öffnet die Truhe und findet..." }, enUS = { completion = "You open the chest to discover...." } })
apply(627, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Hattet Ihr Glück mit dem Blutstein?", completion = "Ah, wunderbar! Dass war ein großer Gefallen, den Ihr mir erwiesen habt.\n\nHier ist Euer Lohn..." }, enUS = { progress = "Hello, {name}.  Did you have luck getting the bloodstone?", completion = "Ah, splendid!  That was a big favor you did for me.\n\nHere is your payment..." } })
apply(628, { "classic", "forever" }, { deDE = { progress = "Irgendwo habe ich gelesen, dass die Salzwasserkrokilisken langsam aussterben... schlecht für mein Geschäft, was?\n\nEgal, ich hoffe, Ihr habt die Haut eines alten Salzwasserkrokilisken für mich!", completion = "Großartig! Dank Eurer Hilfe habe ich diese Bestellung fertig und kann sie mit dem nächsten Schiff zu Direktor Riddlevox nach Undermine abschicken. Sogar noch vor der Frist!\n\nFür all Eure harte Arbeit, hier, ich habe einige zusätzlich gemacht, nehmt Euch ein Paar. Geht auf Drizzliks Rechnung.\n\nUnd denkt dran, nirgends gibt es Stiefel, die so fein, wie Stiefel von Drizzliks Exzelsiorlinie ganz allein!" }, enUS = { progress = "I read somewhere that the saltwater crocolisks are slowly dying out... bad news for my business, isn't it?\n\nAnyways, I hope you have that elder saltwater crocolisk skin for me!", completion = "Great! Thanks to your help I'll have this order filled and sent off to Director Riddlevox on the next boat to Undermine. Ahead of schedule, even!\n\nFor all your hard work, here, I made some extras, so take a pair. It's on Drizzlik.\n\nAnd remember, there's no boot so fine as one of Drizzlik's Excelsior line!" } })
apply(629, { "classic", "forever" }, { deDE = { progress = "Ich warte auf den Schrifttafel-Splitter, {name}.", completion = "Das ist gut. Wenn ich nach Orgrimmar zurückkehre, werde ich diesen Splitter an einen geheiligten Ort legen. Er wird uns an die Macht und Ehre von Gri'lek erinnern.\n\nIch danke Euch, {name}. Eure Taten sind ein Zeichen wachsender Freundschaft mit dem Darkspearstamm." }, enUS = { progress = "I await the Tablet Shard, {name}.", completion = "This is good.  When I return to Orgrimmar I will place this shard in a sacred place.  It will remind us of the might and honor of Gri'lek.\n\nThank you, {name}.  Your deeds mark a growing friendship with the Darkspear tribe." } })
apply(630, { "classic", "forever" }, { deDE = { progress = "Ich danke meinen Vorfahren, dass mir jemand zu Hilfe gekommen ist. Habt Ihr den Schlüssel, der mich befreien kann?", completion = "{name}, Ihr habt mich vor großer Schande bewahrt. Wenn es in meiner Macht stünde, würde ich Euch einen Platz in meinem Stamm anbieten. Alles, was ich Euch zur Zeit anbieten kann, ist jedoch nur diese Marke für den Mut und die edle Gesinnung, die Ihr bewiesen habt." }, enUS = { progress = "I thank my ancestors someone has come to aid me. Do you have the key that will free me?", completion = "{name}, you have saved me from a great dishonor. If it was within my power, I would offer you a place among my tribe. But for now, all I can only offer you is this token for the courage and nobility you have shown." } })
apply(631, { "classic", "forever" }, { deDE = { completion = "Ihr durchsucht den winzigen Zwergenleichnam. Auf dem Helm könnt Ihr die deutlich eingravierten Buchstaben lesen: Ebenezer Rustlocke." }, enUS = { completion = "You search the tiny, dwarven corpse.  Engraved into the helmet you can clearly read: Ebenezer Rustlocke." } })
apply(632, { "classic", "forever" }, { deDE = { progress = "Gibt es Spuren von Ol' Rustlocke, {name}?", completion = "Oh weh, das sind wirklich schlechte Nachrichten." }, enUS = { progress = "Any sign of Ol' Rustlocke, {name}?", completion = "Oh my, the news is grave...." } })
apply(633, { "classic", "forever" }, { deDE = { progress = "Der Behälter mit Sprengstoff muss zerstört werden!", completion = "Die letzte Brücke ist gerettet! Ihr habt König Magni und dem Volk von Khaz Modan einen großen Dienst erwiesen.\n\nJetzt können wir so lange durchhalten, bis Verstärkung kommt..." }, enUS = { progress = "The cache of explosives must be destroyed!", completion = "The remaining bridge is saved!  You have done a great service to King Magni and the people of Khaz Modan.\n\nNow if we can only hold out long enough for reinforcements to show..." } })
apply(634, { "classic", "forever" }, { deDE = { completion = "Longbraid und seine mutigen Soldaten haben mein ehrliches Mitgefühl und Beileid. Die Nachricht von der Tragödie am Thandol-Übergang und der Fall von Dun Modr lastet schwer auf meinem Herzen.\n\nAber Stromgarde ist gefallen! Darum befinden wir uns hier bei der Zuflucht. Wir müssen uns der Wiedereroberung unserer eigenen großen Stadt stellen.\n\nEhre und Pflicht verlangen von uns, dass wir das Hochland nicht verlassen, bis erneut das mächtige Banner des Königs über Stromgarde weht. Ich werde Longbraid Nachricht geben, dass er auf sich allein gestellt ist ..." }, enUS = { completion = "My condolences go out to Longbraid and his brave soldiers.  The news of the Thandol Span tragedy and the fall of Dun Modr hangs heavy in my heart.\n\nBut Stromgarde has fallen!  Hence our presence here at Refuge Pointe.  We are faced with retaking our own great city.\n\nHonor and duty require that we do not leave the Highlands until Stromgarde raises the mighty banner of the King once again. I will send word to Longbraid that he is on his own..." } })
apply(637, { "classic", "forever" }, { deDE = { progress = "Ihr seht aus, als wäret Ihr weit gereist und hättet viel Aufruhr in Eurem Leben erlebt, {class}. Diese Zeit, in der wir leben, ist eine Prüfung für die Seele. Was für Neuigkeiten bringt Ihr denn nun?", completion = "Ihr sagt, Ihr habt meinen Sully unter den eiskalten Wassern gesehen? Sagt, dass das nicht wahr ist!\n\nLasst mich lesen, was er geschrieben hat..." }, enUS = { progress = "You look as though you have traveled a great distance and seen much turmoil in your time, {class}.  These times we live in are trying on the soul.  What news do you bring to me now?", completion = "You say you saw my Sully pinned beneath the icy waters?  Say it isn't so!\n\nLet me read what he wrote...." } })
apply(638, { "classic", "forever" }, { deDE = { completion = "Wie geht‘s denn so, {class}? Die Aufgabe, die Vol'jin uns gestellt hat, wird nicht leicht sein, und jegliche Hilfe, die Ihr uns bieten könnt, ist nicht nur sehr willkommen, sondern auch vonöten." }, enUS = { completion = "How you doing, {class}? The task set before us by Vol'jin will be a difficult one, and any assistance you might provide will be appreciated and necessary." } })
apply(639, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das erste Siegelzeichen bereits gefunden? Höchstwahrscheinlich trägt es einer der Agenten des Syndikats in Stromgarde bei sich.", completion = "Exzellent, Mann. Unsere Suche der Siegelzeichen, die wir sammeln müssen, um Trol'kalar aus Trollbanes Grabmal an uns zu nehmen, hat damit einen guten Anfang genommen." }, enUS = { progress = "Have you located the first sigil yet? It is most likely carried on the person of one of the Syndicate agents in Stromgarde.", completion = "Excellent, mon. That's a good start to collecting the sigils we'll need to remove Trol'kalar from Trollbane's tomb." } })
apply(640, { "classic", "forever" }, { deDE = { progress = "Throm-ka, {class}. Zengu sagte mir, dass Ihr meine Hilfe bräuchtet?", completion = "Ah, ich soll für Euch dieses Siegelzeichen zusammenfügen? Das sollte nicht allzu schwer sein... alle Teile scheinen vorhanden zu sein und die magische Struktur müsste sich leicht wieder herstellen lassen.\n\nIhr solltet vielleicht besser Eure Augen schließen." }, enUS = { progress = "Throm'ka, {class}. Zengu informed me that you required my assistance?", completion = "Ah, you need me to reconstruct this sigil? It shouldn't be too difficult... all the pieces seem to be here and the magical structure will be easy to reform.\n\nYou might want to close your eyes." } })
apply(641, { "classic", "forever" }, { deDE = { progress = "{name}! Habt Ihr das zweite Siegelzeichen?", completion = "Wir haben unsere Aufgabe, Trol'kalar aus Trollbanes Grabmal an uns zu nehmen, zur Hälfte erfüllt. Wir sind nicht ganz sicher, wo sich das dritte Siegelzeichen befindet, da seine Bewacher allem Anschein nach viel in Arathi umherreisen, aber ich bin der festen Überzeugung, dass Ihr in der Lage seid, es aufzuspüren." }, enUS = { progress = "{name}! Do you have the second sigil?", completion = "We're halfway to being able to remove Trol'kalar from Trollbane's tomb. We are not exactly sure where the third sigil is, as its holders seem to move around Arathi quite a bit, but I have faith that you'll be able to find it." } })
apply(642, { "classic", "forever" }, { deDE = { progress = "Diese Gruppe von Splittern sieht den Splittern von Myzrael sehr ähnlich. Aber durch sie pulsiert kein Gefühl der Sicherheit.", completion = "Ah! Ihr habt diese Splitter aktiviert! Ich fühle mich schon mehr wie ich selbst!\n\nAber weh mir, ich bin immer noch weit davon entfernt, frei zu sein..." }, enUS = { progress = "This cluster of shards looks much like the Shards of Myzrael.  But the same feeling of security does not pulse through them.", completion = "Ah!  You activated these shards.  Already I feel more myself!\n\nBut alas, I am still far from free..." } })
apply(643, { "classic", "forever" }, { deDE = { progress = "Heldenruf wird nicht so leicht zu finden sein, {name}. Zu Pferd kann er weite Strecken schnell zurücklegen. Dessen ungeachtet müssen wir dieses Siegelzeichen haben.", completion = "Ihren Anführer der Kavallerie zu verlieren, wird den Verteidigern von Stromgarde einen schweren Schlag versetzen. Und was noch besser ist, es bedeutet, dass wir nur noch ein Siegelzeichen davon entfernt sind, Trol'kalar unser Eigen nennen zu können." }, enUS = { progress = "Valorcall will not be easy to track down, {name}. Mounted on horseback, he can cover ground quickly. Nonetheless, we must have his sigil.", completion = "Losing their cavalry leader will prove a large blow to the Stromgarde defenders. Better yet, it means that we are only one sigil from being able to have Trol'kalar for ourselves." } })
apply(644, { "classic", "forever" }, { deDE = { progress = "Ihr seid zurückgekehrt, {name}. Ist die Linie des Ignaeus Trollbane zerbrochen?", completion = "Was für ein Tag, {class}. Das Blut der Trollbane wird nicht länger mein Volk verfolgen und die Siegelzeichen, die wir brauchen, um Trol'kalar an uns zu nehmen, befinden sich allesamt in unserem Besitz. Bald schon, sehr bald, werden wir gegen die verhassten Trolle von Zul'Gurub losschlagen können." }, enUS = { progress = "You've returned, {name}. Is the line of Ignaeus Trollbane broken?", completion = "Quite a day this is, {class}. The blood of Trollbane will no longer haunt my people, and the sigils needed to take Trol'kalar are in our possession. Soon, very soon, we will strike against the hated trolls of Zul'Gurub." } })
apply(645, { "classic", "forever" }, { deDE = { progress = "Gravuren auf dem Stein auf der Oberseite von Trollbanes Grabmal zeichnen genau die glühenden Linien des Siegelzeichens von Ignaeus nach...", completion = "Nachdem die Linien auf dem Stein auf der Oberseite von Trollbanes Grabmal genau den glühenden Linien des Siegelzeichens von Ignaeus angeglichen wurden, wird das Siegelzeichen von einem Lichtblitz eingehüllt und das legendäre Schwert Trol'kalar wird aus der Umklammerung der steinernen Hand freigegeben." }, enUS = { progress = "Etchings in the stone upon the face of the tomb of Trollbane match the glowing lines of the Sigil of Ignaeus...", completion = "Matching the lines on the face of Trollbane's tomb with the glowing lines of the Sigil of Ignaeus, a flash of light consumes the Sigil, and the legendary sword Trol'kalar is released from the stone hands' grip." } })
apply(646, { "classic", "forever" }, { deDE = { progress = "{name}! Habt Ihr das Schwert geholt?", completion = "Generation um Generation haben die Streitkräfte von Strom und Arathor die Trolle vernichtet. Jetzt ist ihre größte Waffe in unseren Händen. Unsere winzigen Fortschritte in den dampfenden Wäldern von Zul'Gurub gehören der Vergangenheit an.\n\nIhr wart eine große Hilfe, {name}, und die Trolle der Darkspear stehen tief in Eurer Schuld.\n\nIch werde sicherstellen, dass das Schwert zu Nimboya in Grom'gol gebracht wird." }, enUS = { progress = "{name}! Have you taken the sword?", completion = "For generations, the forces of Strom and Arathor ravaged the trolls. Now their greatest weapon is in our hands. Our inching progress in the steamy forests of Zul'Gurub will be no more.\n\nYour assistance has been great, {name}, and the Darkspear trolls are indebted to you.\n\nI will be sure that the sword is delivered to Nimboya at Grom'gol." } })
apply(647, { "classic", "forever" }, { deDE = { progress = "Na, wie läufts denn, {race}?", completion = "Es geht doch nichts über Foggy MacKreels Fusel, der einem an kalten Tagen so richtig das Herz wärmt. Und ich dachte schon, der kleine Scheißer würde wieder mal mit der Bezahlung auf sich warten lassen. Ich danke Euch, Freund! Vielen herzlichen Dank!" }, enUS = { progress = "What's the good word, {race}?", completion = "Ah, nothing like Foggy MacKreel's Moonshine to warm you up on a brisk day!  And here I was thinking the little bugger was going to be overdue on his bills again. Thank you, friend!  Many thanks indeed!" } })
apply(648, { "classic", "forever" }, { deDE = { completion = "Oh, IHR seid also der großartige Retter von OOX-17/TN! Ich kann Euch gar nicht sagen, wie dankbar ich für Eure Hilfe bin! Die Entwicklung meiner Serie von Leitrobotern ist noch nicht abgeschlossen, aber Eure Rettungsaktion hat mir ungezählte Stunden Bauzeit erspart, sowie ebenso viele Goldstücke an Kosten für eine Neukonstruktion!\n\nBitte sucht Euch einen von diesen Gegenständen hier aus. Hoffentlich könnt Ihr einen davon gebrauchen. Ich danke Euch nochmals für Eure großzügige Hilfe, meine Roboter und ich stehen tief in Eurer Schuld!" }, enUS = { completion = "Oh, YOU'RE the great savior of OOX-17/TN!  I cannot even begin to express my thanks for your assistance!  My homing robot series needs more developing, but your recovery has saved me countless hours of rebuilding time, as well as many gold pieces in rebinding costs!\n\nPlease, take your choice of any of these items I have.  Hopefully, you will make good use of one of them.  Thank you again for your generous assistance, my robots and I are in your debt!" } })
apply(649, { "classic", "forever" }, { deDE = { completion = "Ach ja, wegen der Welle, die mein Vater möchte! Er will die Welle an eine Taverne hier in Orgrimmar verkaufen, aber wir würden mehr Geld bekommen, wenn sie sich in der Originalverpackung befinden würde. Ich kenne da jemanden, der das machen kann, und er befindet sich im Hinterland, wo auch die Welle ist. Aber er ist, ähm, ein Hochelf.\n\nNa ja, er ist ein guter Hochelf, da er kein Anhänger der Allianz ist. Na ja, er ist weniger ein guter Hochelf als ein betrunkener Hochelf. Er liebt und ich meine LIEBT den Alkohol." }, enUS = { completion = "Oh yeah, about the ripple dad wants!  He wants to sell the ripple to a tavern here in Orgrimmar, but we'll get more money if it is in its original packaging.  I know someone who can do that, and he's in the Hinterlands where the ripple is.  But he's, um, a high elf.\n\nWell, he's a good high elf, as he's not a part of the Alliance.  Well, he's not so much a good high elf as he is a drunken high elf.  He loves, and I mean LOVES the hooch." } })
apply(650, { "classic", "forever" }, { deDE = { completion = "Ah, Ihr kennt also Malton? Er ist ein alter Saufkumpan von mir. Seht, ich habe etwas gefunden, das die Grenzen künstlicher Verträge und Allianzen überspringt - Alkohol. Wenn wir alle unseren Durst an seinen glückseligen Qualitäten löschen würden, würden wir uns spirituell an einem viel besseren Ort befinden.\n\nAber etwas sagt mir, dass Euer Besuch hier nicht dem Zweck dient, etwas über die erlösenden Werte des Alkohols zu erfahren, nicht wahr?" }, enUS = { completion = "Ah, so you know Malton?  He is an old drinking companion of mine.  You see, I have found something that transcends the boundaries of artificial treaties and alliances - alcohol.  Were we all to slake our thirsts on its blissful qualities, we all would be in a much better place spiritually.\n\nAlas, something tells me that your visit here is not to learn of alcohol's redeeming values, now is it." } })
apply(651, { "classic", "forever" }, { deDE = { progress = "Dies ist der Stein der inneren Bindung. Er ist der stärkste der Bindungs-Steine und muss erst aufgeschlossen werden, damit die anderen sich öffnen.", completion = "<Myzrael spricht durch den Stein.>\n\nIhr habt es geschafft! Ihr habt die Steine der Bindung geöffnet! Ich fühle, wie meine Fesseln sich lösen und die Freiheit immer näher rückt.\n\nIhr seid ein edelmütiger {class}, {name}. Mein Retter!" }, enUS = { progress = "This is the Stone of Inner Binding.  It is the strongest of the binding stones and must be unlocked for the others to open.", completion = "<Myzrael speaks through the stone.>\n\nYou have done it!  You opened the Stones of Binding!  I can feel the shackles about me loosen, and freedom draws ever closer.\n\nYou are a noble {class}, {name}.  My rescuer!" } })
apply(652, { "classic", "forever" }, { deDE = { progress = "Der Hauptstein ist mit einer enormen geomantischen Energie aufgeladen.", completion = "Ihr platziert die Rute im Hauptstein. Und fühlt unter Euch eine Erschütterung..." }, enUS = { progress = "The Keystone is charged with tremendous geomantic energy.", completion = "You place the rod in the keystone.  And a shudder is felt beneath you..." } })
apply(653, { "classic", "forever" }, { deDE = { completion = "Die Fürstin sagte mir, dass Ihr kommen würdet, {class}. Ihr seid in meiner Hütte willkommen, denn Ihr dient einem höheren Ziel, genau wie ich selbst." }, enUS = { completion = "The Lady told me of your coming, {class}.  You are welcome in my abode for you, like I, serve a higher cause." } })
apply(654, { "classic", "forever" }, { deDE = { progress = "Na, habt Ihr alles bekommen, was Ihr benötigt? Falls Ihr es nicht geschafft habt und die Kraftquelle erschöpft ist, ist alles im Inneren ruiniert und Ihr müsst wieder von vorn beginnen.\n\nHey, erwartet von mir kein Mitgefühl; mich interessiert nur, ob die Gadgetzan Water Company Profit macht, und wenn das bedeutet, dass ich Euch Kraftquellen verkaufe, bis wir es uns leisten können, Wasser von den eisigen Quellen von Dun Morogh zu importieren, dann sei es so!", completion = "Also gut, ich benötige nur einen Moment, um die Kraftquelle zu entfernen. Danach könnt Ihr damit machen, was Ihr wollt, ohne Euch darum sorgen zu müssen, dass Ihr die Daten im Inneren verliert." }, enUS = { progress = "Well, did you get everything you needed?  If you didn't and the power runs out, everything inside will be ruined and you'll have to start over.\n\nHey, don't look to me for sympathy; I'm all about the Gadgetzan Water Company making a profit, and if that means selling you power sources until we can afford to import water in from the icy springs of Dun Morogh, so be it!", completion = "All right then, it will take me just a second to remove the power source.  After that, you can do with it whatever you like now without having to worry about losing the data inside." } })
apply(655, { "classic", "forever" }, { deDE = { completion = "Ach, Ihr sprecht von Gor'mul. Ja, von dem, was er so erzählt, scheint es, als hätte er sich niemals ganz vom Tod Doomhammers erholt.\n\nGor'mul war Gefangener hier als Thrall und Orgrimm um die Befreiung des Lagers kämpften, aber als die Erde bebte und unsere Brüder entkamen, blieb er hier zurück. Er wanderte jahrelang allein und verloren ohne Richtung oder Hoffnung umher, bis wir zurückkamen, um uns hier in Hammerfall eine Heimat aufzubauen." }, enUS = { completion = "Ah, Gor'mul you speak of. Yes, from what he says, it seems he has never recovered from the death of Doomhammer.\n\nGor'mul was a captive here when Thrall and Orgrim fought to free the camp, but as the earth shook and our brethren escaped, he was left behind. He wandered alone and lost for years without direction or hope, until we returned to establish ourselves here in Hammerfall." } })
apply(656, { "classic", "forever" }, { deDE = { progress = "Die Splitter von Myzrael sind jetzt seltsam ruhig.", completion = "Als die geisterhaften Fesseln um die Splitter gelegt werden, ist von tief unten ein unmenschliches Heulen zu hören. Dem Heulen folgt ein Brüllen.\n\nDie Splitter von Myzrael rufen nicht mehr das gleiche Gefühl von Wärme und Sicherheit hervor, wie es zuvor der Fall war. Jetzt pulsieren sie mit einer offenen Bedrohung... als ob das, was sich unterhalb befindet, der Oberfläche Böses will." }, enUS = { progress = "The Shards of Myzrael are now strangely quiet.", completion = "As the eldritch shackles are placed around the Shards, an unhuman wail is heard from far below.  The scream is followed by a roar.\n\nThe Shards of Myzrael no longer invoke feelings of warmth and security as they once did.  Now they pulse with an open menace... as if the thing beneath them holds ill will toward the surface." } })
apply(657, { "classic", "forever" }, { deDE = { completion = "Wenn es Phin was hilft, zerquetsche ich jeden Einzelnen der Verlassenen höchstpersönlich. Seit der Seuche hat er so viel für uns getan. Niemand von uns hätte gedacht, dass wir noch mal Familie oder Freunde wiedersehen würden.\n\nWenn Ihr fertig seid, gebt mir Bescheid. Dann können wir sofort beginnen." }, enUS = { completion = "If it brings Phin peace, I'll destroy every single one of the Forsaken personally. He's done so much for us since the plague. We never thought we'd find friends or family again.\n\nWhen you're prepared, come let me know. We'll get started right away." } })
apply(658, { "classic", "forever" }, { deDE = { progress = "Wir danken für Eure Hilfe bei der Suche nach diesem Kurier, {name}.\n\nWährend Ihr fort wart, konnte Kin einen Apotheker beobachten, der aus demselben Haus südlich von hier herauskam. Ich bin ziemlich sicher, dass sie nichts Gutes im Schilde führen - aber ich brauche Beweise, bevor wir unüberlegt einfach drauflos hauen.\n\nHattet Ihr Glück?", completion = "Exzellent! \n\nDann lasst uns mal sehen, was das alles soll..." }, enUS = { progress = "We appreciate your help in looking for that courier, {name}.\n\nWhile you were gone, Kin saw an apothecary come out of that same house to the south of here. I'm confident that they're up to no good--I just need proof of it before we go off and do something rash.\n\nHave you had any luck yet?", completion = "Excellent! \n\nLet's see what this is about..." } })
apply(659, { "classic", "forever" }, { deDE = { completion = "Versucht so leise wie möglich zu sein, Reisender.\n\nOrcs mögen es gar nicht, wenn sie bespitzelt werden, und auf dieser Farm ist mehr los als der erste Anblick es vermuten lässt." }, enUS = { completion = "Try and stay as quiet as possible, traveler.\n\nOrcs don't take too well to being spied on, and there is more to this farm than meets the eye." } })
apply(660, { "classic", "forever" }, { deDE = { progress = "Die Zeit der Gespräche ist vorbei. Wenn Euch die Bewohner von Hillsbrad auch nur das Geringste bedeuten, dann beschützt Ihr Kinelory.", completion = "Ihr habt uns einen großen Dienst erwiesen, {name}. Danke.\n\nIch hoffe, Kin hat Euch da unten nicht zu sehr auf Trab gehalten. Sie ist sehr freundlich, aber sie kann genauso tödlich sein, wenn Ihr sie zum Feind habt." }, enUS = { progress = "The time for talk is done. Protect Kinelory if you care about the people of Hillsbrad at all.", completion = "You've done a great service for us, {name}. Thank you.\n\nI hope Kin wasn't too much of a handful down there. She's very friendly, but can be just as deadly when you're her enemy." } })
apply(661, { "classic", "forever" }, { deDE = { completion = "Also geht's den beiden Unruhestiftern doch gut? Haha, es freut mich, das zu hören. Ich danke Euch, dass Ihr mir von ihrem Aufenthaltsort und Status berichtet habt - es freut mich sehr, dass sie noch am Leben sind, die beiden sind als Freunde und Reisegefährten praktisch unersetzlich.\n\nAber ... es ist wichtiger, dass ich Euch richtig für Eure Hilfe danke. Hier, nehmt dies, zusammen mit dem Dank meiner Gruppe.\n\nMit ein wenig Glück können wir herausfinden, was die Verlassenen vorhaben und dem ein Ende bereiten." }, enUS = { completion = "So, the two troublemakers are all right after all? Haha, I'm glad to hear it. I thank you for bringing me news of their whereabouts and status--it pleases me greatly that they are still alive; the two of them are irreplaceable as friends and traveling companions.\n\nBut... it's more important I thank you properly for your help. Here. Take this along with my group's thanks.\n\nWith any luck, we'll figure out what the Forsaken are up to, and put an end to it." } })
apply(662, { "classic", "forever" }, { deDE = { progress = "Wie läuft die Suche und Bergungsmission, {name}? Diese Karten und Logbücher von der TOLLEN MINNA und der SILBERGEIST brauchen wir wirklich.\n\nWenn die Informationen aus diesen Quellen in Feindeshand gelangen, lässt Flottenmeister Seehorn uns über die Planke laufen.\n\nDas heißt, natürlich nur, wenn wir jemals aus diesem Schlamassel rauskommen...", completion = "Dass diese Informationen gesichert sind, wird das Kommando in Booty Bay etwas beruhigen. Gut gemacht, {name}." }, enUS = { progress = "How goes the search and recovery mission, {name}?  We really need to get those Logs and Charts back from the Maiden's Folly and Spirit of Silverpine.\n\nIf the information from those sources were to fall into enemy hands, Fleet Master Seahorn would force us down the plank.\n\nThat is if we ever get out of this mess...", completion = "Knowing this information is secure will bring some ease to the command in Booty Bay.  Well done, {name}." } })
apply(663, { "classic", "forever" }, { deDE = { completion = "Ahoi, Kumpel.\n\n's war fürchterlich. Seehorn wird mir mein Schiff nehmen, wenn er rausfindet, was los war.\n\nEiner der Apparate des Professors zeigte an, dass der verlorene Schatz in der Nähe dieser Bucht zu finden sei. Ich hab die HARBINGER anlegen lassen und der SILBERGEIST und der TOLLEN MINNA signalisiert, das Gleiche zu tun.\n\nDann rumpelte das Meer. Die Tide senkte sich ab und die beiden Schiffe krachten in das Riff.\n\nEs ist nicht nur ein Riff. Da unten ist etwas...\n\nHelft meiner Crew und Ihr werdet reich belohnt." }, enUS = { completion = "Ahoy, matey.\n\n'Twas a horrible mess. Seahorn will have my ship if he finds out what went down.\n\nOne of the Professor's contraptions indicated the lost treasure was near this cove. I brought the Harbinger in to dock and signaled for the Spirit of Silverpine and Maiden's Folly to follow suit.\n\nThen the sea rumbled. The tides lowered and the two ships crashed into the reef.\n\nIt's not just a reef. Something's down there....\n\nHelp my crew out and you'll be rewarded handsomely." } })
apply(664, { "classic", "forever" }, { deDE = { completion = "Ihr habt da draußen gute Arbeit geleistet, {name}.\n\nDieser Abschaum hat bekommen, was er verdient. Auch wenn nichts auf der Welt mir jemals mein Schiff oder meine Crew zurückbringen wird, der Tod der Naga tröstet mich ein wenig." }, enUS = { completion = "Nice work out there, {name}.\n\nThose scum deserved what they got. While nothin' will ever bring me ship or me crew back, the death of those naga gives me some solace." } })
apply(665, { "classic", "forever" }, { deDE = { progress = "Jetzt ist nicht die Zeit zum Reden! Die Schutzbrille muss mit der Kraft des Steins aufgeladen werden!", completion = "Jetzt funktioniert die Schutzbrille perfekt! Gut gemacht, {name}." }, enUS = { progress = "This is no time to talk! The goggles need to be charged with the power of the stone!", completion = "The goggles work perfectly now! Well done, {name}." } })
apply(666, { "classic", "forever" }, { deDE = { progress = "Wie lief es mit der Schutzbrille? Hat alles korrekt funktioniert? Änderungen können durchgeführt werden, falls es notwendig ist.\n\nOh, und ich brauche die Schutzbrille zurück, wenn Ihr fertig seid. Ich bin sicher, Kapitän O'Breen wird sie später für verschiedene Dinge gut gebrauchen können.", completion = "Absolut superb, {name}. Der Kapitän wird sehr erfreut sein! Und wartet nur, bis Flottenmeister Seehorn davon erfährt!" }, enUS = { progress = "How did the goggles work? Did everything function properly? Adjustments can be made if necessary.\n\nOh, and I'll need those goggles back when you're done. I am sure Captain O'Breen will have many uses for them later on.", completion = "Most superb, {name}! The Captain will be very pleased! And just wait until word gets back to Fleetmaster Seahorn!" } })
apply(667, { "classic", "forever" }, { deDE = { completion = "Wir haben den Angriff überlebt!\n\nOhne Euch hätten wir es nicht geschafft, {name}.\n\nSobald die Flut kommt, werden wir hier wegsegeln. Wenn Ihr nicht ein so viel versprechender Held wärt, würde ich Euch einen Platz in meiner Crew anbieten. Aber ich seh schon, Ihr habt Größeres vor.\n\nAuch wenn Ihr nur ein schwacher {race} seid..." }, enUS = { completion = "We survived the attack!\n\nWe could not have done it without you, {name}.\n\nWe'll be heading out as soon as the tide rises. If you weren't such a promising hero I'd offer you a place on my crew. But I can tell you have bigger fish to fry.\n\nEven if you are a puny {race}...." } })
apply(668, { "classic", "forever" }, { deDE = { progress = "Ahoi, {class}. Was führt Euch auf die Brücke?", completion = "Also haben die kleinen Gnome doch bewiesen, dass sie was wert sind? Wusste ich doch, dass wir diese Wadenbeißer nicht umsonst behalten haben!" }, enUS = { progress = "Ahoy, {class}.  What brings you to the bridge?", completion = "So the little gnomes proved their worth after all? I knew we kept those ankle biters around for a reason!" } })
apply(669, { "classic", "forever" }, { deDE = { progress = "Was führt Euch nach Booty Bay, {class}?", completion = "Ah, der gute alte Shakes O'Breen schafft es doch immer! Ich wusste, dass er der richtige Kapitän für diese Mission war!" }, enUS = { progress = "What brings you to Booty Bay, {class}?", completion = "Ah, leave it to good old Shakes O'Breen! I knew that he was the right Captain for the mission!" } })
apply(670, { "classic", "forever" }, { deDE = { progress = "War Seehorn beeindruckt? Ich wette mit Euch, sein Grinsen reichte von Booty Bay bis Ratchet.", completion = "Ich danke Euch, dass Ihr eine solch lange und gefährliche Reise auf Euch genommen habt. Die Dankbarkeit der Schwarzmeerräuber ist Euch sicher." }, enUS = { progress = "So was Seahorn impressed? I bet you his smile reached from Booty Bay to Ratchet.", completion = "Thank you for making such a long and perilous journey. You have the gratitude of the Blackwater Raiders." } })
apply(671, { "classic", "forever" }, { deDE = { progress = "Ich habe immer noch einstmals verfluchtes Blut in meinen Adern, {name}. Wenn jemand... etwas Dämonen beschwört, muss das beendet werden.", completion = "Ich werde einige Zeit brauchen, bis ich die wahren Absichten des Syndikats enthüllen kann, aber ihre offensichtliche Verbindung zur dunklen, dämonischen Magie beunruhigt mich sehr. Ich werde Euch Nachricht geben, sobald ich mehr weiß." }, enUS = { progress = "Once-cursed blood still runs through my veins, {name}. If someone... something is summoning demons, it must be stopped.", completion = "It will take some time for me to ascertain the true intentions of the Syndicate, but their obvious association with dark, demonic magic troubles me. I will tell you when I know more." } })
apply(672, { "classic", "forever" }, { deDE = { progress = "Ich werde ein Amulett herstellen, das Gor'mul ein wenig Raptorenkraft verleiht. Vielleicht kann das ein kleines Feuer in ihm entfachen...", completion = "Exzellent. Die Geister der Raptoren, die uns diese Augen gaben, werden dem Träger dieses Amuletts Kraft verleihen." }, enUS = { progress = "I will create an amulet that will give Gor'mul some of the strength of the raptors. Perhaps that will awaken some flame within him...", completion = "Excellent. The spirits of the raptors that gave these eyes will lend strength to the bearer of this amulet." } })
apply(673, { "classic", "forever" }, { deDE = { progress = "Das Brennen in meinem Blut... es wird mit jedem Tag stärker. Der Hexenmeister muss aufgehalten werden.", completion = "Meine rastlosen Nächte werden sich in einen friedvollen Schlummer wandeln, sobald ich diese Kugel zerstört habe. Danke, {name}. Es ist eine eiskalte Erinnerung an die grausame Macht, die die Dämonen über die Orcs hatten, bevor Hellscream uns von ihrem Fluch befreit hat." }, enUS = { progress = "The burning in my blood... it grows by the day. The warlock must be stopped.", completion = "My restless nights will turn to peaceful slumber when I have destroyed this orb. Thank you, {name}. It is a chilling reminder of the terrible power the demons held over the orcs before Hellscream released them from their curse." } })
apply(674, { "classic", "forever" }, { deDE = { progress = "Welche Hoffnung gibt es noch, wenn der Mächtigste der Mächtigen durch die Hand eines Feiglings erschlagen werden kann? Welche Hoffnung, sagt es mir?", completion = "Was ist dies? Polierte Knochen. Was soll ich mit polierten Knochen anfangen? Wird so ein Tand die Horde wieder zu ihrem alten Ruhm führen?" }, enUS = { progress = "What hope is there when the hand of a coward can slay the mightiest of the mightiest? What hope, I ask you!", completion = "What is this? Polished bone. What use have I for polished bone? Will a trinket restore the Horde to its glory?" } })
apply(675, { "classic", "forever" }, { deDE = { completion = "Wie ich sehe, hat es nicht funktioniert. Nichtsdestotrotz glaube ich, dass die Vorführung der Schamanen-Macht Gor'mul schließlich doch wieder zu seinem ehemals stolzen Selbst zurückführen kann. Die Macht des Amuletts war einfach nicht stark genug, um ihn von unserer wiedergefundenen Macht zu überzeugen." }, enUS = { completion = "It did not work, I see. Nonetheless, I feel that showing him the power of the shamans will eventually return Gor'mul to his once proud self. The amulet's power was not great enough to show him our newfound power." } })
apply(676, { "classic", "forever" }, { deDE = { completion = "Ihr denkt also, Ihr seid stark genug, um Hammerfall zu helfen? So sei es denn.\n\nTallow hat Euch zu dem Ogerhort geschickt, weil er entweder hoffte, dass Ihr dort umkommt, oder denkt, dass Ihr stark genug seid, um uns zu helfen. Auf jeden Fall seid Ihr jetzt hier, und ich benötige dringend mehr Soldaten in unserem Kampf gegen die ständigen Angriffe.\n\nWenn Ihr länger in Hammerfall bleiben wollt, dann ruht Euch ein wenig aus und meldet Euch wieder bei mir, wenn Ihr bereit seid. Ihr werdet noch mehr als genug Gelegenheit zum Kämpfen haben." }, enUS = { completion = "So, you think you're strong enough to help Hammerfall? So be it.\n\nTallow either sent you to that ogre mound in the hopes that you would kill yourself or he thinks you're strong enough to aid us. Either way, you're here now and I am in need of more soldiers in our fight against the constant attacks.\n\nIf you plan on staying in Hammerfall then get some rest, and come speak to me again when you're ready. There's no shortage of fighting to be had." } })
apply(677, { "classic", "forever" }, { deDE = { completion = "Die Zeichen des Krieges sind auf Eurer Kleidung und Schweiß tropft von Euren Brauen. Das ist gut, sogar sehr gut." }, enUS = { completion = "The signs of war are upon your garments, and sweat drips from your brow. Good, very good indeed." } })
apply(678, { "classic", "forever" }, { deDE = { completion = "Ihr seid ebenso stark wie ein Kodo und Eure Kampfeslust macht Eurem Volk alle Ehre." }, enUS = { completion = "You are as strong as a kodo, and your lust for battle does your people proud." } })
apply(679, { "classic", "forever" }, { deDE = { completion = "Euer Volk kann stolz auf Euch sein, {name}. Die Bedrohung konnte um ein Vielfaches verringert werden und ich bin überzeugt, dass wir uns hier im Hochland bald sehr heimisch fühlen werden." }, enUS = { completion = "You do your people proud, {name}. The threat has been greatly lessened, and I am sure we will begin to thrive here in the Highlands." } })
apply(680, { "classic", "forever" }, { deDE = { progress = "Ihr werdet Or'Kalar nahe dem Turm von Arathor finden. Sein Tod bedeutet das Ende der Angriffe auf Hammerfall und Schutz für das Leben meines Gemahls.\n\nIch sehe in Euren Augen, dass Ihr mich für schwach haltet - vielleicht sogar für unehrenhaft -, weil ich geschwiegen habe. Eines Tages werdet auch Ihr lernen, was es heißt, so zu lieben, wie ich es tue. Vielleicht werdet Ihr dann eine etwas andere Art von Stärke und Ehre verstehen können.\n\nAber bis dahin, tut, um was ich Euch bitte, und erschlagt Or'Kalar.", completion = "Ihr habt mir einen großen Dienst erwiesen, {name}. Denn wisset, dass durch Eure Taten das Leben meines Gemahls und die Sicherheit von Hammerfall für einen weiteren Tag gewährleistet wurden. Bitte nehmt das als Belohnung für Euren Mut." }, enUS = { progress = "Near the Tower of Arathor--that is where you will find Or'Kalar. His death will stop the attacks on Hammerfall and protect my husband's life.\n\nI see in your eyes that you think me weak--even dishonorable--for my silence. Some day you will learn what it is to love as I do. Perhaps then you will understand a different kind of strength and honor.\n\nIn the meantime, do as I ask, and slay Or'Kalar.", completion = "You have done me a great service, {name}. Know that my husband's life and the safety of Hammerfall has been protected for another day because of your deeds. Please take this as a reward for your courage." } })
apply(681, { "classic", "forever" }, { deDE = { progress = "{name}, mit jeder Stunde wird unsere Kontrolle über Stromgarde schwächer. Ihr müsst Euch beeilen, anderenfalls wird unsere Stadt gewiss fallen.", completion = "Sehr gut, {name}. Mit dem Tod dieser Syndikatsmitglieder sollte es leichter werden, Vorräte aus Southshore zu erhalten.\n\nVielleicht besteht für unsere Sache ja noch Hoffnung." }, enUS = { progress = "{name}, with each passing hour our hold on Stromgarde grows more tenuous.  You must make haste or our city will surely fall.", completion = "Very good, {name}.  With the deaths of those Syndicate members we should have an easier time receiving supplies from Southshore.\n\nPerhaps our cause yet has hope." } })
apply(682, { "classic", "forever" }, { deDE = { progress = "Konntet Ihr Abzeichen von Stromgarde finden, {name}? Das Syndikat muss begreifen, dass sie mit unseren Toten keinen Profit machen können.", completion = "Ich danke Euch, {name}. Wir werden die Familien dieser getöteten Soldaten davon in Kenntnis setzen, dass sie im Kampf gefallen sind.\n\nEs ist bestimmt furchtbar, so eine grausame Nachricht zu erhalten, aber es ist allemal besser, als wenn das Schicksal einer geliebten Person für immer ungewiss bleibt." }, enUS = { progress = "Have you retrieved any Stromgarde Badges, {name}?  The Syndicate must learn they cannot profit from our dead.", completion = "Thank you, {name}.  We will inform the families of these fallen soldiers that they were killed in battle.\n\nIt will be grim news to bear, but it is better than the uncertainty of a missing loved one." } })
apply(683, { "classic", "forever" }, { deDE = { progress = "Ihr seid also {name}, der {class}? Neuigkeiten über Eure Hilfe gegenüber der Allianz sind weit gereist, wisst Ihr?\n\nIn welcher Angelegenheit tretet Ihr heute vor mich?", completion = "Es wird nur einen Augenblick dauern, um diesen Brief zu überfliegen..." }, enUS = { progress = "So you are {name} the {class}? News of your contributions to the Alliance has traveled quite far, you know?\n\nOn what business do you come before me today?", completion = "It will take but a moment for me to peruse this letter..." } })
apply(684, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, {class}. Kommt Ihr, um Bericht zu erstatten?", completion = "Ihr habt Marez Cowl erledigt? Gut gemacht, {name}. Wirklich gute Arbeit!\n\nMarez bedrohte unsere Verteidiger von Stromgarde und es wurde gemunkelt, dass sie Abgesandte zwischen dem Syndikat und einer anderen, dunkleren Macht war. Wir sind froh, dass sie nicht länger ihre Kräfte gegen uns einsetzen kann." }, enUS = { progress = "Greetings, {class}.  You have a report to make?", completion = "You took down Marez Cowl?  Well done, {name}.  Well done indeed!\n\nMarez menaced our Stromgarde defenders, and it is rumored she was an emissary between the Syndicate and some other, darker power.  We are glad to see that she'll no longer ply her powers against us." } })
apply(685, { "classic", "forever" }, { deDE = { progress = "Hallo. Kommt Ihr, um Bericht zu erstatten?", completion = "Falkenstein und Otto? Wunderbar!\n\nHier ist Eure Belohnung, {name}. Ich freue mich, sie auszuzahlen." }, enUS = { progress = "Hello.  Do you have a report to submit?", completion = "Falconcrest and Otto?  Wonderful!\n\nHere is your reward, {name}.  I am happy to pay it." } })
apply(686, { "classic", "forever" }, { deDE = { completion = "Also, König Magni Bronzebeard hat Euch höchstpersönlich vorbeigeschickt?\n\nMeine Güte! Dann muss es wichtig sein!" }, enUS = { completion = "So King Magni Bronzebeard himself sent ye?\n\nMy, my! This must be important!" } })
apply(687, { "classic", "forever" }, { deDE = { completion = "Hallo. Hallo, hallo hallo hallo hallo HALLO!\n\nTut mir Leid - Moment, nein, stimmt gar nicht! Seid nicht unhöflich!\n\nOh nein... das war verrücktes Geschwätz.\n\nAllerdings... verrückt zu sein, ist manchmal mein einziger Trost." }, enUS = { completion = "Hello.  Hello, hello hello hello hello HELLO!\n\nI'm sorry - wait, no I'm not!  Don't be rude!\n\nOh no...that was crazy talk.\n\nBut...sometimes being crazy is my only solace." } })
apply(688, { "classic", "forever" }, { deDE = { completion = "Willkommen, {class}. Die Fürstin hat mich von Eurem Kommen unterrichtet, und wenn wir sie zurück an die Oberfläche bringen wollen, dann haben wir viel zu besprechen." }, enUS = { completion = "Welcome, {class}.  The Lady has informed me of your coming, and if we are to bring her back to the surface then we have much to discuss..." } })
apply(689, { "classic", "forever" }, { deDE = { progress = "{name}, {name}, {name}! Sagt mir, dass Ihr genügend Alteracgranit beschafft habt, damit ich mein Meisterwerk zu Ehren von Sully Balloo beginnen kann.", completion = "Perfekt! Besser als ich es mir vorstellen konnte!\n\nUnd ich habe ziemlich viel Phantasie, wisst Ihr..." }, enUS = { progress = "{name}, {name}, {name}! Tell me you have enough Alterac Granite for me to begin my masterpiece in honor of Sully Balloo.", completion = "Perfect! Better than I could have imagined!\n\nAnd I have quite an imagination you know..." } })
apply(690, { "classic", "forever" }, { deDE = { completion = "Malin hat Euch also geschickt? Is' mir egal, ob Muradin von den Toten auferstanden ist und Euch auf'm Drachen hergeflogen hat. Ich hab zu tun! Redet mit Kryten, wenn Ihr was braucht." }, enUS = { completion = "So, Malin sent ye? I don't care if Muradin rose up from the dead and whisked ye here on a dragon. I'm busy! Talk to Kryten if you need somethin'." } })
apply(691, { "classic", "forever" }, { deDE = { progress = "Habt Ihr schon Glück gehabt, {name}?\n\n\n\nWenn meine Forschungen richtig sind, sollten die Hauer von einem Troll der Witherbark stammen. Ich brauche die Medizinbeutel von Hexendoktoren der Witherbark und die stärksten ihrer Schattenjäger sollten die Spezialmesser bei sich tragen, die sie erhalten, nachdem sie die Aufnahmeriten absolviert haben. Welche Schattenjäger ein solches Messer besitzten, könnt Ihr nur herausfinden, wenn Ihr gegen sie kämpft.", completion = "Unglaublich! Jetzt durchschaue ich, warum Malin Euch gebeten hat, sich uns anzuschließen - das habt Ihr wahrlich sehr gut gemacht!\n\nWenn das so weitergeht, können Skuerto und ich im Handumdrehen nach Stormwind zurückkehren.\n\nIch glaube, mein Zwergengefährte ist aus der Halle der Felsfäuste zurück; sprecht mit ihm, wenn Ihr bereit seid.\n\nScheint so, als hätte er eine kleine Balgerei mit den Ogern gehabt. Erwähnt das ihm gegenüber aber nicht, er ist sehr sensibel, was Kritik an seinen Späherfertigkeiten angeht." }, enUS = { progress = "Have you had any luck so far, {name}?\n\n\n\nIf my research is correct, the tusks should come from any Witherbark troll. The medicine pouches come from the Witherbark witch doctors, and the strongest of the Witherbark shadow hunters should carry the special knife given to them after they've completed their rites of passage. There's no way to tell which shadow hunters will have the knife until you do battle.", completion = "Incredible! I can see why Malin asked you to come join us--very well done indeed!\n\nAt this rate, Skuerto and I will be headed back to Stormwind in no time at all.\n\nI believe my dwarven companion is back from scouting Boulderfist Hall; go speak to him when you're ready.\n\nIt looked as though he might have had a bit of a scuffle with the ogres. Don't mention that to him, though; he's very sensitive about criticisms to his skills at scouting." } })
apply(692, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Fragmente gefunden?!? Ihr braucht die Rolle von Myzrael, wenn Ihr sie wieder einsperren wollt, bevor es zu spät ist!", completion = "Ah, Ihr habt sie gefunden! Gut gemacht, {name}! Das könnte die einzige Chance sein, die wir gegen das Böse von Myzrael haben!\n\nLasst mich nur kurz meine Schrott-Ratsche suchen und schauen, ob ich diese Fragmente wieder anfügen kann..." }, enUS = { progress = "Did you find those fragments?!?!  You'll need the Scroll of Myzrael if you want to trap her again, before it's too late!", completion = "Ah, you found them!  Good work, {name}! These might be the only chance we have against the evil of Myzrael!\n\nJust let me find my scrap-ratchet and see if I can re-attach these fragments..." } })
apply(693, { "classic", "forever" }, { deDE = { progress = "Unser Ziel ist der Zauberstab, {name}. Konzentriert Euch vorerst nur darauf.", completion = "Genial, {name}. Einen Gegenstand haben wir, fehlen nur noch drei, laut meiner Liste. Die anderen drei Gegenstände befinden sich alle in Stromgarde.\n\nRuht Euch eine Weile aus, damit Ihr wieder zu Kräften kommt - die nächste Phase meines Plans erfordert etwas mehr Zeit und Mühe. Kommt wieder zu mir, wenn Ihr etwas Warmes im Bauch und Euch ausgeruht habt." }, enUS = { progress = "Our goal is the wand, {name}. Focus on that for now.", completion = "Brilliant, {name}. One item down an' three more to go, based on my list. The other three items are all in Stromgarde.\n\nTake a rest an' get your strength back--the next phase of my plan'll require a little more time an' effort. Come back to me after you've gotten a warm meal an' some rest." } })
apply(694, { "classic", "forever" }, { deDE = { progress = "Da seid Ihr ja wieder, {name}. Habt Ihr schon einen azurblauen Achat gefunden?", completion = "Ihr erstaunt mich, {name}. Gut gemacht.\n\nGebt mir einen Moment Zeit, um den richtigen Zauber auf den Edelstein zu wirken, dann ist alles bereit." }, enUS = { progress = "{name}, hello again. Have you found an azure agate yet?", completion = "You amaze me, {name}. Well done again.\n\nGive me a moment to cast the proper spell to enchant the gem, an' you'll be ready." } })
apply(696, { "classic", "forever" }, { deDE = { progress = "Wenn Ihr das tut, wird Malin sicherlich mehr als zufrieden mit Euch sein.", completion = "Malin hätte niemanden bitten können, uns zu helfen, der fähiger wäre als Ihr, {name}. Ihr habt hervorragende Arbeit geleistet!\n\nEr wird sich freuen zu sehen, was für ein überwältigender Erfolg unsere Mission geworden ist." }, enUS = { progress = "You do this, an' I'm sure Malin'll be more than pleased with you.", completion = "Malin couldn't've asked a worthier person to come here an' aid us, {name}. You've done a grand job!\n\nHe'll be pleased to see what an overwhelming success our mission's been." } })
apply(697, { "classic", "forever" }, { deDE = { progress = "Ja? Ihr kommt mir irgendwie bekannt vor. Entschuldigt bitte, aber sind wir uns schon mal begegnet? Ich bin so beschäftigt, dass ich manchmal den Überblick verliere.", completion = "<Erzmagier Malin öffnet den Brief und seine Augen weiten sich.>\n\nBeim Licht, Ihr habt es geschafft! Wie wunderbar. Trelane wird hocherfreut sein. Ich bin sicher, Kryten und Skuerto sind ebenso aufgeregt wie ich, dass sie endlich auf dem Rückweg nach Stormwind sind.\n\nDanke, {name}. Bitte, nehmt dies hier, es soll Euch auf Euren Reisen helfen." }, enUS = { progress = "Yes? You look vaguely familiar. I do apologize, but have we met? I get so busy I lose track.", completion = "<Archmage Malin opens the letter, and his eyes grow wide.>\n\nBy the Light, you've done it. How wonderful. Trelane will be so pleased. I'm sure Kryten and Skuerto are just as excited as I am to have them on their way back to Stormwind.\n\nThank you, {name}. Please, take this to help you in your journeys." } })
apply(698, { "classic", "forever" }, { deDE = { progress = "Lok-Tar, {class}. Das Risiko einer Reise durch die Sümpfe nimmt man nicht leichtfertig auf sich. Sehr mutig von Euch, Euren Mut gerade hier auf die Probe zu stellen.", completion = "Ah! Großartig. Frisches Fleisch für unsere Feier heute Abend. Danke, {name}.\n\nIhr habt dazu beigetragen, die Nächte hier erträglicher zu machen. Das Feuer brennt hell und unsere Mägen werden wohl gefüllt sein.\n\nWas für eine angenehme Überraschung, die Ihr uns da gebracht habt; Dar mag zwar nicht gerade der attraktivste Orc sein, den man je gesehen hat, aber dafür ist seine Einstellung besser als sein Ruf." }, enUS = { progress = "Lok'tar, {class}. Traveling through the swamps isn't a risk taken lightly. You're brave to test your mettle here.", completion = "Ah! Wonderful. Fresh meat for the fire tonight. Thank you, {name}.\n\nYou've helped make the coming nights more tolerable. The fire burns bright, and our stomachs will be full.\n\nIt's a pleasant surprise to have you bring us a shipment; Dar's not the most attractive orc anyone's laid eyes upon, but at least his attitude reeks far less than his smell." } })
apply(699, { "classic", "forever" }, { deDE = { progress = "Guter Met, ein warmes Feuer, eine Armee von Orcs, ein Arsenal von Waffen... das ist alles, was wir hier draußen entlang der Küste brauchen. Ich bedauere nicht, dass ich hier draußen bin und Stonard bewache, aber es wäre nett, wenn wir eines Tages mal einen Bau oder zumindest einen Turm hätten.", completion = "Wie schön zu sehen, dass Ihr lebt und wohlauf seid, {name}.\n\nDiese Klauen eignen sich bestens. Je mehr Waffen wir zur Verfügung haben, um uns gegen Angreifer zu verteidigen, desto besser für uns.\n\nIch fange sobald wie möglich mit der Fertigung Eurer Waffe an. Ich werde nicht lange brauchen. Ich habe ein ziemliches Geschick dafür entwickelt und die Herstellung geht mir schnell von der Hand." }, enUS = { progress = "Good mead, a warm fire, an army of orcs and an arsenal of weapons... that's all we really need out here along the coast. I don't regret my position out here safeguarding Stonard, but it would be nice if we could one day get a burrow, or at least a tower.", completion = "Glad to see you're alive and well, {name}.\n\nThese claws should make do nicely. The more weapons we have at the ready for attacks against us, the better off we'll be.\n\nI'll get started on your weapon as soon as possible. It will only take a short time. I've become quite adept and quick at their production." } })
apply(700, { "classic", "forever" }, { deDE = { completion = "Der Granit ist im Vergleich zum Lebenswerk eines großen Zwergs nur ein kleiner Ausdruck der Wertschätzung. Kein Zwerg kann jedoch ewig auf diesem Planeten wandeln.\n\nHoffen wir nur, dass der Gedenkstein eine Mahnung an all jene ist, die in Zukunft das große Azeroth betreten. Wir dürfen nie vergessen, dass es mutige Soldaten wie Sully Balloo waren, die so tapfer ihr Leben gaben, denen wir das alles verdanken." }, enUS = { completion = "The granite seems but a small token compared to a great dwarf's life. But no dwarf shall last on this planet for eternity.\n\nLet us just hope that the memorial stands as a reminder to those who will trod the great Azeroth of the future.  Lest we not forget it is for them that brave soldiers such as Sully Balloo so valiantly gave their lives." } })
apply(701, { "classic", "forever" }, { deDE = { progress = "All meine Vorbereitungen sind getroffen, jetzt brauche ich nur noch die Raptorherzen.", completion = "Ja, die eignen sich hervorragend. Ich werde die Macht und den Geist der Raptoren hier auf diese Kugel übertragen. Diese Kugel wird Gor'mul die feurige Kraft und Intelligenz des Raptors verleihen." }, enUS = { progress = "My preparations are made, all I require are the raptor hearts.", completion = "Yes, these will work perfectly. I will transfer their power and the spirit of the raptors into this orb. This orb will imbue Gor'mul with the fiery strength and intelligence of the raptor." } })
apply(703, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Bringt Ihr mir die Flügel?", completion = "Ah, ich fange gleich mit der Zubereitung der Flügel an. Ich kann sie schon förmlich schmecken!\n\nUnd hier habt Ihr das Rezept, falls Ihr sie einmal selbst zubereiten wollt!" }, enUS = { progress = "Hello, {name}.  Did you bring me my wings?", completion = "Ah, I'll get started on those wings right away.  I can almost taste them already!\n\nAnd here's the recipe in case you want to make them yourself!" } })
apply(704, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Urnen gefunden, {name}? Wir müssen herausfinden, welche Verbindung zwischen ihnen und den Troggs besteht!", completion = "Gut gemacht! Mit Glück und Geschick werden wir herausfinden, welche Verbindung zwischen den Troggs und diesen uralten Artefakten besteht. \n\nIhr habt den Ausgrabungsleitern einen großen Dienst erwiesen, {name}. Eure Bemühungen werden wir Euch nicht vergessen! Und Agmond ebenso wenig." }, enUS = { progress = "Did you find those urns, {name}?  We must find the link between them and the troggs!", completion = "Well done!  With luck and diligence, we will find whatever link exists between the troggs and these ancient artifacts.  \n\nYou have done a great deed for the Prospectors, {name}.  Your efforts will not be forgotten.  And neither will Agmond." } })
apply(705, { "classic", "forever" }, { deDE = { progress = "Habt Ihr meine Perlen? Ich habe fast keine Blitzstrahlbomben mehr!", completion = "Die eignen sich hervorragend! Ich muss sie nur noch zu Pulver zermahlen... dann mit einem bisschen hiervon und einem bisschen davon vermischen.\n\nObacht, Aasfresser! Bald trifft euch der Blitzstrahl!" }, enUS = { progress = "Did you get my pearls?  I'm almost out of flash bombs!", completion = "These will work great!  I just need to smash them into powder...then mix them with a little of this and a little of that.\n\nWatch out, scavengers!  Prepare to be flashed!" } })
apply(706, { "classic", "forever" }, { deDE = { progress = "Wie läuft die Jagd, {class}?", completion = "Ah ja, ausgezeichnet. Damit können Eure Waffen mit sengender Hitze zuschlagen!" }, enUS = { progress = "How goes the hunt, {class}?", completion = "Ah yes, this will do excellently. This will enable your weapons to strike with searing heat!" } })
apply(707, { "classic", "forever" }, { deDE = { completion = "Stormpike hat Euch also hergeschickt, was? Gut.\n\nIch habe eine große Aufgabe für Euch..." }, enUS = { completion = "So Stormpike sent you, did he?  Good.\n\nI have a big task for you..." } })
apply(709, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Schrifttafel gefunden? Sie enthält bestimmt Geheimnisse! Geheimnisse, die uns retten können!", completion = "Oh, das Glück ist uns hold! Danke! Wir sind gerettet!" }, enUS = { progress = "Did you find the tablet?  It must hold secrets!  Secrets to save us!", completion = "Oh, fortune is with us!  Thank you!  We may yet be saved!" } })
apply(710, { "classic", "forever" }, { deDE = { progress = "Dieses Gebiet eignet sich perfekt für - könntet Ihr das einen Moment festhalten? Ja, genau so, parallel zum Normalvektor. Also, wo war ich... Richtig. Perfekt, um mein neuestes Projekt zu testen. Die Rohstoffe, das offene Gelände... was könnte sich ein intelligenter und erleuchteter Fachmann der Technik sonst noch wünschen?", completion = "Die eignen sich bestens, {name}. Danke. Hmm, ein bisschen mehr Sand als ich erwartet hatte. Muss den Reibungskoeffizienten anpassen. Nein, Sekunde; das sollte sich mit dem Frostöl ausgleichen lassen." }, enUS = { progress = "This area's perfect for-- Could you hold these in place for a moment? Yes, just like that, along the vector normal. Now, what was I... Right. Perfect for testing my latest project. The raw materials, the open space... what more could an intelligent and enlightened practitioner of the arts ask for?", completion = "These shall do nicely, {name}. Thank you. Hmm, a bit more sand than I'd anticipated. Have to adjust the coefficient of friction. No, wait; it should still be negligible with the frost oil." } })
apply(711, { "classic", "forever" }, { deDE = { progress = "Ich bin hoch erfreut, {name}. Meine Zauber haben auf die kleineren Stücke gewirkt, wie ich voraussagte. Falls dieses Experiment so erfolgreich ist, wie ich voraussehe, dann werden die Elementare, die ich beherrschen kann, alles andere, was ich bislang beschworen habe, in den Schatten stellen.", completion = "Einfach erstaunlich, {name}! Ich hätte gedacht, man würde mindestens ein halbes Dutzend Tauren benötigen, um das alles hierher zu schleppen." }, enUS = { progress = "I'm most pleased, {name}. My spells affected the smaller pieces just as I predicted. If this experiment is as successful as I foresee, then the elementals I'll be able to control will put anything summoned prior to this to shame.", completion = "{name}, simply amazing! I would have thought it'd take half a dozen tauren to bring all these to me." } })
apply(712, { "classic", "forever" }, { deDE = { progress = "Die Steinplatten, die Ihr mir gebracht habt, waren ideal, {name}. Lucien wird die restlichen nach Kharanos zurückbringen, wenn wir hier fertig sind. Sie könnten sich später noch als nützlich erweisen.\n\nSie würden sich zum Beispiel gut eignen, um einen praktischen kleinen Bunker zu bauen, sobald ich mit einem fachübergreifenden Feldversuch an hoch wirksamem Sprengstoff beginne...", completion = "{name}, habt Ihr jemals darüber nachgedacht, Forschungsassistent zu werden? Nein? Ich weiß wirklich nicht, wie ich ohne Eure Fähigkeiten hier auskommen soll. Intelligenz, Neugier und Kraft - alles zusammengeschnürt in einem Paket." }, enUS = { progress = "The stone slabs you found were ideal, {name}. Lucien will be taking the extra ones back to Kharanos when we're done here. After all, they could prove useful again.\n\nFor instance, they'd be a nice basis for a handy little shelter once I start looking into a multidisciplinary approach to high-yield explosives...", completion = "{name}, have you ever considered becoming a research assistant? No? I'm not sure what I'll do without your abilities here. Intelligence, curiosity, and strength--all combined into one package." } })
apply(713, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Öl schon gefunden, das ich benötige? Es würde mir sehr helfen, wenn Ihr mir etwas davon bringen würdet.", completion = "Toll! Das dürfte das perfekte Kühlmittel für meine neuen Armschienen sein. Wenn diese Verzauberung nicht mindestens ein Jahrhundert hält, schenke ich all meine Habseligkeiten Servo.\n\nAlle Magier der Vereinigung werden vor Ehrfurcht erstarren, wenn ich damit fertig bin, {name}. Wartet's nur ab." }, enUS = { progress = "Have you found the oil I need? It would be so helpful if you were able to find some.", completion = "Stupendous! This should be the perfect coolant for my new bracers. If the enchantments don't last a century, then I'll give all my belongings to Servo.\n\nAll the mages of the Assembly will be in such awe after I finish this, {name}. You just wait and see." } })
apply(714, { "classic", "forever" }, { deDE = { progress = "Ja, ja, ja. Nur einen Moment.\n\n<Lotwil setzt seine Arbeit an irgendeiner Art von Apparat fort.>", completion = "HA!\n\n<Lotwil schnappt sich das Gyrochronatom von Euch.>\n\nPerfekt... so gut wie fertig. Nein, ehrlich. Ich BIN jetzt fast fertig. Dieses Projekt hat oberste Priorität... im Moment. Lasst mich das hier noch an die richtige Stelle stecken, und Ihr könnt selbst sehen, wobei Ihr mir geholfen habt. Es wird nur noch ein paar Minuten dauern... vielleicht... möglicherweise etwas länger. Na gut, vielleicht sehr viel länger. Wir werden ja sehen..." }, enUS = { progress = "Yes, yes, yes. Just a moment.\n\n<Lotwil continues to work on some kind of contraption.>", completion = "HA!\n\n<Lotwil grabs the gyrochronatom from you.>\n\nPerfect... just about done. No, really. I AM almost done now. This project is my top priority... at the moment. Let me pop this into place, and you can see for yourself what you've helped me create. It'll just take me a few more minutes... maybe... possibly longer. Well, maybe a lot longer. We'll see..." } })
apply(715, { "classic", "forever" }, { deDE = { progress = "Er ist bald fertig. Wie sieht es denn bei Euch aus?", completion = "JA!\n\nIch meine, danke, {name}. Sie werden bei Reisen durchs Ödland sehr hilfreich sein." }, enUS = { progress = "He's getting closer to finishing. How are things going on your end?", completion = "YES!\n\nI mean, thank you, {name}. These will be helpful while traveling through the Badlands." } })
apply(716, { "classic", "forever" }, { deDE = { progress = "Ich würde nicht zu lang warten, um mir diese Armschienen zu holen, {name}.\n\nWer weiß, was als Nächstes passieren wird?", completion = "Bitte sehr, {name}. Probiert sie mal an." }, enUS = { progress = "I wouldn't wait too long to get that bracer, {name}.\n\nWho knows what's going to happen next?", completion = "Here you go, {name}. Try these on." } })
apply(717, { "classic", "forever" }, { deDE = { progress = "Starke Magie und Mächte haben die Drachen so lange Zeit gefangen gehalten, aber wir dürfen keinesfalls zulassen, dass Schattenbringer und Hematus irgendwie freikommen.", completion = "Die Kirin Tor müssen sich keine Sorgen wegen der Gefangenen von Lethlor machen. Ich werde zurückkehren und meinem Meister von diesem Erfolg berichten. Krasus wird zweifellos erfreut sein." }, enUS = { progress = "Strong magics and powers held the drakes' prison for so long, but we cannot allow any possibility that Blacklash and Hematus may be released.", completion = "No longer will the Kirin Tor need to worry over the prisoners of Lethlor. I will return to report success to my master. Krasus will no doubt be pleased." } })
apply(718, { "classic", "forever" }, { deDE = { progress = "Die Wüste ist für einen Hungrigen ein schlechter Ort, mein Freund, das könnt Ihr mir glauben.\n\nHe... was ist denn das da drüben...", completion = "Vielen Dank, {name}. Während Ihr fort wart, habe ich, äh... einen Mund voll Sand gegessen. Es...\n\nAch, genug davon; wir ziehen aus und besorgen uns heute Abend etwas zu essen. Wir werden wie Könige speisen!" }, enUS = { progress = "The desert's a bad place to be hungry, my friend, let me tell you that.\n\nHey... what's that over there...", completion = "Thanks so much, {name}. While you were gone, I... er... swallowed a mouthful of sand. It...\n\nWell, enough of that, we'll go out and get some food tonight. Eat like kings!" } })
apply(719, { "classic", "forever" }, { deDE = { progress = "Keine Ahnung, wonach die Zwerge der Schattenschmiede suchen, aber die hatten definitiv einen Grund.", completion = "Ihr seid mein Retter, {class}. Ich bin ja so froh, dass endlich mal jemand den Zwergen der Schattenschmiede gezeigt, was eine Harke ist. Danke für Eure Hilfe." }, enUS = { progress = "Not sure what the Shadowforge were lookin' for, but they definitely had a purpose.", completion = "Ye're me savior, {class}. I'm glad someone could teach those Shadowforge a lesson or two. Thanks for yer help." } })
apply(720, { "classic", "forever" }, { deDE = { completion = "Hammertoe lebt?! Das ist ja wunderbar, {name}!" }, enUS = { completion = "Hammertoe's alive?! This is amazin', {name}!" } })
apply(721, { "classic", "forever" }, { deDE = { completion = "Ja? Tut mir Leid... (((hustet))) Fühl mich so schwach. Könnt Ihr 'n bisschen näher kommen, {class}?\n\nRyedol schickt Euch? Muradin sei gelobt, dieser Junge hat doch mehr auf dem Kasten als ich dachte. (((hustet)))" }, enUS = { completion = "Yes? Ah'm sorry... <cough> Feel so weak. Can ye come closer, {class}?\n\nRyedol sent ye? Muradin be praised, that boy's not as slow in the head as I once thought." } })
apply(722, { "classic", "forever" }, { deDE = { progress = "Der Schattenschmiedeklan... <hustet>... ist gefährlich. Seid vorsichtig. <hustet>... Ihr müsst das Amulett finden.", completion = "Ha! (((hustet)))\n\nAh, ich wusste, dass Ihr mein Amulett finden würdet, {name}.\n\n(((keucht))) Sehr gut, wirklich, {name}. (((hustet)))" }, enUS = { progress = "The Shadowforge clan... <cough> is dangerous. Be careful. <cough> You must find the amulet.", completion = "Ha! <cough cough>\n\nAh knew you'd find me amulet, {name}.\n\n Well done indeed, {name}." } })
apply(723, { "classic", "forever" }, { deDE = { progress = "Ich würde sagen, dass war ein öder Tag, aber das hier ist das Ödland. Jeder Tag ist öde.", completion = "Hammertoes Amulett? Ich glaube, ich war besserer Stimmung, als ich noch dachte, er sei tot. Es jetzt endgültig zu wissen, macht den Schmerz noch schlimmer. Das Amulett war sein Lebenswerk. Sein Tod soll nicht umsonst gewesen sein." }, enUS = { progress = "I'd say it was a bad day, but this is the Badlands: every day's a bad day.", completion = "Hammertoe's amulet? I think my spirits were higher when I thought he was dead. Knowin' fer sure only makes the pain worse. This amulet was his life's work. I can't let his death be in vain." } })
apply(724, { "classic", "forever" }, { deDE = { progress = "Ah, ja. Wieder ein Reisender, der nach etwas von den Zwergen sucht.\n\nSire, es tut mir wirklich Leid, aber ich habe jetzt keine Zeit, sinnlose Fragen zu beantworten.", completion = "Oh! Ja, das ist eine ganz andere Sache. Ihr habt vielleicht noch nicht die Schwere dieser Angelegenheit erkannt, was?\n\nIch bin zutiefst erschüttert über Hammertoes Ableben, aber wenn er Euch mit seinem Amulett zu mir geschickt hat, dann wusste er genau, was auf dem Spiel steht.\n\nWir werden später noch Zeit haben, seinen Tod zu betrauern.\n\nLasst mich Euch einen der Gründe zeigen, warum dieses Amulett so wertvoll ist." }, enUS = { progress = "Ah, yes. Another traveler seeking something from the dwarves.\n\nSir, I'm truly sorry, but I've no time to answer meaningless questions right now.", completion = "Oh! Well, this is a different matter entirely. You probably don't realize the gravity of this matter yet, do you?\n\nI care deeply about Hammertoe's demise, but if he sent you here with his amulet, then he understood what's at stake.\n\nWe will have to take time to mourn his death later.\n\nLet me show you one of the reasons this amulet is so valuable." } })
apply(725, { "classic", "forever" }, { deDE = { progress = "Hmm? Ja, {class}.", completion = "Ah, eine Nachricht von Historiker Karnik. Exzellent.\n\nFür ihn habe ich immer Zeit.\n\n<Berater Belgrum öffnet die Notiz und beginnt zu lesen.>" }, enUS = { progress = "Hmm? Yes, {class}.", completion = "Ah, word from Historian Karnik. Excellent.\n\nI always have time for his business.\n\n<Advisor Belgrum opens the note and begins to read.>" } })
apply(726, { "classic", "forever" }, { deDE = { completion = "Ihr behandelt diese Angelegenheit mit einer Dringlichkeit, die der des Königs in nichts nachsteht, {name}.\n\nAlso gut. Ich weiß, wie wir die Zwerge der Schattenschmiede in die Knie zwingen können.\n\nWir können ihre Unternehmungen in Uldaman verlangsamen, wenn wir sie an ihrem Operationsstützpunkt schlagen: der Festung Angor." }, enUS = { completion = "You're treating this matter with an urgency I'd expect from the king himself, {name}.\n\nAll right, then. I know what'll bring the Shadowforge down.\n\nTheir presence in Uldaman can be slowed if we strike them at their base of operations: Angor Fortress." } })
apply(727, { "classic", "forever" }, { deDE = { progress = "Hallo. Willkommen in meinem Laden, aber passt auf, was Ihr berührt.\n\nWissen kann manchmal tödlich sein.", completion = "Oh. Seid gegrüßt, Bruder.\n\nUnd gelobt die Bewohner der Tiefe." }, enUS = { progress = "Hello.  Welcome to my shop, but watch what you touch.\n\nKnowledge can be deadly.", completion = "Oh.  Greetings, brother.\n\nAnd praise to the dwellers beneath." } })
apply(728, { "classic", "forever" }, { deDE = { progress = "Ah, Ihr seid ein besonders eifriger {class}, wie ich sehe. Seid Ihr hier, um aus meiner Sammlung zu lernen? Gut!\n\nAber seid gewarnt: Genau wie Wissen den Starken Macht verleiht... treibt es die Schwachen in den Wahnsinn.", completion = "Seid diskret mit Euren Zeichen, {class}. Manche werden Euch die Rechtschaffenheit Eures Anliegens nicht abnehmen.\n\nUnd es gibt einige, die gern Zeuge unseres Versagens wären, würden sie von uns wissen.\n\nWir müssen immer vorsichtig sein. Und wachsam. Und geduldig." }, enUS = { progress = "Ah, we have an eager {class}, I see.  Are you here to learn from my collection?  Good!\n\nBut be warned: just as knowledge gives power to the strong...it will drive the weak mad.", completion = "Be discrete with your signs, {class}. There are those who do not believe the righteousness of our pledge.\n\nAnd there are those who would see us fail if they knew of us.\n\nWe must always be careful.  And watchful.  And patient." } })
apply(729, { "classic", "forever" }, { deDE = { completion = "Hollee, seid Ihr das? Ich brauche jemanden, der mir hilft, diesen Stein zu bearbeiten. Gebt mir meinen Handfeger, ich glaube, ich sehe was.\n\nHe, Ihr seid gar nicht Hollee! Ihr habt nicht zufällig meinen Handfeger gesehen?\n\nIst ja jetzt auch egal! Ich habe denen von der Liga versprochen, das rätselhafte Fossil zu schicken, das ich gefunden habe. Wo ist Hollee nur wieder hin?\n\nEs gibt noch so viel zu tun! Also wo ist jetzt dieses rätselhafte Fossil ... und mein Feger ... und Hollee ...\n\nUnd wer seid Ihr ... Ist ja auch egal, Hauptsache, Ihr seid hier, um mir zu helfen.\n\nLasst es mich wissen, wenn Ihr bereit seid zu suchen." }, enUS = { completion = "Hollee, is that you? I need some help chiseling this stone. Hand me my stone brush, I think I see something.\n\nHey, you're not Hollee! Don't suppose you've seen my stone brush?\n\nNever mind that now! I promised the League I'd send the mysterious fossil I found. Where did Hollee go?\n\nSo much work to be done! Now where is that mysterious fossil... and my brush... and Hollee...\n\nAnd who are you... 'tis no matter, so long as you're here to help.\n\nLet me know when you're ready to start looking." } })
apply(730, { "classic", "forever" }, { deDE = { completion = "Ich bin ja so froh, dass Chefarchäologe Greywhisker nach uns schicken ließ..." }, enUS = { completion = "I'm so glad Chief Archeologist Greywhisker sent for us...." } })
apply(731, { "classic", "forever" }, { deDE = { completion = "Den Sternen sei Dank, Ausgrabungsleiter Remtravel ist in Sicherheit! Ich sagte Euch doch, dass er etwas geistesabwesend ist. Nicht zu fassen, dass er darauf bestanden hat, trotz all dieser schrecklichen Kreaturen, die dort herumschleichen, zu bleiben." }, enUS = { completion = "Thank the stars Prospector Remtravel is safe! I told you he was absent minded. I can't believe he insisted on staying there with all of those horrible creatures lurking about." } })
apply(732, { "classic", "forever" }, { deDE = { progress = "Die nomadisierende Ogerbande zieht von einem ihrer Lager im Ödland zum nächsten, die Hitze, die von der trockenen Erde aufsteigt, und die wirbelnden Winde erschweren es, ihren Spuren zu folgen. Ich habe gehört, dass sie gelegentlich durch das Camp Boff reisen. Falls Ihr nicht so recht weiter wisst, könnt Ihr ja mal dort suchen.", completion = "Das sind wahrlich gute Neuigkeiten, dass Ihr mir das Zeichen bringt, {name}. Das Zeichen der Erde wurde von den Dunkeleisenzwergen der Festung Angor geschaffen, um zwei unbarmherzige Deathwing-Lieutenants, die Zwillinge Schattenbringer und Hematus, zu binden." }, enUS = { progress = "The nomadic band of ogres travels between their camps across the Badlands; heat rising from the dry earth and the swirling winds will make it difficult to track their progress.  I have heard that sometimes they travel through Camp Boff.  If you are lost, you might try your search there.", completion = "Good tidings you bring bearing the Sign, {name}. The Sign of the Earth was created by the Dark Iron dwarves of Angor Fortress to bind two of Deathwing's ruthless lieutenants, the twins Blacklash and Hematus." } })
apply(733, { "classic", "forever" }, { deDE = { progress = "Tja, ich hab mich mit dem begnügt, was ich bekommen habe... aber es war nicht viel. Habt Ihr noch mehr Vorräte gefunden?", completion = "Es ist ein Anfang, {name}, und es muss reichen, bis wir etwas aus Ironforge oder von der Forscherliga hören.\n\nWenn ich jetzt nur noch etwas Salz für mein Kühlfass finden würde..." }, enUS = { progress = "Well, I've made do with what I could, but... it's not much. Have you found any more supplies?", completion = "It's a start, {name}, and it'll have to do until we hear word from Ironforge or the Explorers' League.\n\nNow, if only I could find some salt somewhere for my quenching barrel..." } })
apply(734, { "classic", "forever" }, { deDE = { completion = "Ein Zahnrad Nr. 5, oh? Tja, das sieht nicht gut aus." }, enUS = { completion = "Cog #5, huh? Yeah, this isn't going to be good." } })
apply(735, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Relikte, um die ich gebeten habe?", completion = "Ihr seid sehr einfallsreich, {class}. Wenn es wirklich Euer Begehr ist, ein neues Kapitel über unseren Orden zu beginnen, dann glaube ich, dass es Euch gut gelingen wird." }, enUS = { progress = "Do you have the relics for which I asked?", completion = "You are resourceful, {class}.  If it truly is your charge to begin a new chapter of our order, then I believe you will run it well." } })
apply(737, { "classic", "forever" }, { deDE = { progress = "Ho! Ihr wart aber lange fort. Habt Ihr die Zusammenstellung?", completion = "Ihr habt sie! Oh, ein Hoffnungsschimmer!\n\nEure Bemühungen könnten uns retten, {name}. Man sollte Euch ein Denkmal errichten! Einen Schrein sollte man bauen! Möge Euer Name gelobt sein, bis Eure Enkel selbst Enkel haben!\n\nEs sei denn... SIE sind frei und steigen an die Oberfläche. Wenn das geschieht, könnt Ihr das mit Kindern gleich vergessen.\n\nWenn SIE frei sind, dann sind wir alle Futter für die Würmer." }, enUS = { progress = "Ho!  You were gone a long time.  Did you get the digest?", completion = "You got it!  Oh, hope glimmers!\n\nYour efforts may yet save us, {name}.  A monument they should make of you!  A shrine they should build!  May your name be praised until your grandchildren have grandchildren!\n\nUnless...THEY are freed and rise to the surface.   If that happens then you can forget about children.\n\nIf THEY are freed, then we're all worm food." } })
apply(738, { "classic", "forever" }, { deDE = { completion = "Dieses Skelett, das müssen die traurigen Überreste Agmonds sein. Sein Körper ist zerschlagen und zerschmettert, die Knochen sind blankgenagt." }, enUS = { completion = "This skeleton must be the unfortunate remains of Agmond.  His body is broken and battered, and his bones picked clean." } })
apply(739, { "classic", "forever" }, { deDE = { completion = "Das sind ernüchternde Neuigkeiten, {name}. Aber Agmond hatte einen starken Arm und einen erbarmungslosen Schlag mit seinem Hammer und sein Schädel war so dick wie kein anderer! Er wurde zwar von diesen verfluchten Troggs getötet, aber ich bin mir sicher, dass er eine Menge von ihnen mit in den Tod genommen hat." }, enUS = { completion = "This is sobering news, {name}.  But Agmond had a strong arm and a fierce hammer-swing, and his skull was as thick as they come!  Although he was killed by those cursed troggs I'm sure he took a lot of them down with him." } })
apply(741, { "classic", "forever" }, { deDE = { progress = "Was kann ich für Euch tun, {race}?", completion = "Oha! Überlassen wir es Ausgrabungsleiter Remtravel, etwas über dieses Fundstück herauszufinden!" }, enUS = { progress = "What can I do for you, {race}?", completion = "Oh my! Leave it to Prospector Remtravel to discover such a find!" } })
apply(742, { "classic", "forever" }, { deDE = { completion = "Willkommen an der neuen Grenze, {name}. Ashenvale ist ein Land der unbegrenzten Möglichkeiten, eines, in dem jemand Eurer Art, {class}, jede Menge Gelegenheiten finden wird, seinen Mumm unter Beweis zu stellen. Schaut Euch hier im Außenposten um und begebt Euch auf jeden Fall auch einmal hinaus zum Zoramstrand, denn die Horde hat dort noch einen weiteren Außenposten.\n\nEure Anwesenheit hier sagt mir, dass Ihr gekommen seid, um mehr über die Jagd zu lernen. Hört mir genau zu, und ich werde euch gern mitteilen, was Ihr wissen müsst." }, enUS = { completion = "Welcome to the new frontier, {name}.  Ashenvale is a land of opportunity, one where a young {class} like yourself is able to find boundless chances to prove their mettle.  Look around the outpost here, and be sure to travel out to the Zoram Strand, as the Horde has another outpost there as well.\n\nYour presence here tells me that you've come to learn more about the hunt.  Listen close, and I will gladly share with you what you need to know." } })
apply(743, { "classic", "forever" }, { deDE = { progress = "Die Windfurien sind tödliche Feinde. Ihre Kampfkraft wird nur von ihrer Gier nach Frischfleisch übertroffen.", completion = "Das habt Ihr gut gemacht, {name}. Ihr scheint gut vorbereitet zu sein, um weiterzureisen. Mögt Ihr stets Rückenwind haben." }, enUS = { progress = "The Windfuries are deadly foes. Their strength in battle is only rivaled by their desire for fresh meat.", completion = "You have done well, {name}. You seem well prepared to travel onward. Let the wind always be at your back." } })
apply(744, { "classic", "forever" }, { deDE = { progress = "Der Kopfputz wird bestimmt ein wunderbares Geschenk für meinen Bruder werden.", completion = "Danke für Eure Hilfe, {name}.\n\nMein Part für die Zeremonie zu Ehren meines Bruders ist fast abgeschlossen. Jetzt muss ich ihm nur noch diesen Kopfputz geben und an der Zeremonie teilnehmen." }, enUS = { progress = "This headdress will certainly be a wonderful gift for my brother.", completion = "Thank you for your help, {name}.\n\nMy part in my brother's ceremony is almost complete. Giving him his headdress and witnessing the ceremony are all my duty requires of me." } })
apply(745, { "classic", "forever" }, { deDE = { completion = "Es ist gut, dass Ihr meine Aufgabe so ernst genommen habt, {name}. Respekt vor dem Land und seinen Kreaturen ist wichtig. Tod und Leben bilden einen Kreis... eine Notwendigkeit. Das eine kann nicht ohne das andere existieren. Nehmt Euch einen Moment Zeit, um darüber nachzudenken, und vergesst es niemals." }, enUS = { completion = "{name}, it is good you've taken my task seriously. Respect of the land and its creatures is important. Death and life are a circle... a necessity. One cannot exist without the other. Take time to ponder this and do well to never forget it." } })
apply(746, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Habt Ihr die zerbrochenen Werkzeuge? Die Graberei der Zwerge wird die Kodos von Mulgore wütend machen. Diese Besudelung muss aufhören!", completion = "Danke, {name}. Das wird die Wildtiere von Mulgore beruhigen. Und, so die Geister gewillt sind, es wird die Zwerge lehren, dass die Aushöhlung des Landes nicht der Weg zu Wissen ist." }, enUS = { progress = "Hello, {name}.  Do you have the Broken Tools?  The dwarves' digging will enrage the kodos of Mulgore.  This defilement must be stopped!", completion = "Thank you, {name}.  This will calm the beasts of Mulgore.  And, spirits willing, it will teach the dwarves that hollowing the land is not the path to knowledge." } })
apply(747, { "classic", "forever" }, { deDE = { progress = "Den Stamm mit Fleisch und Federn zu versorgen, das ist der erste Schritt, Euch dem Häuptling als Jäger zu beweisen.", completion = "Die {race} von Narache danken Euch, {name}. Das war sehr vielversprechend." }, enUS = { progress = "Providing meat and feathers for the tribe is the first step in proving yourself as a hunter before the Chief.", completion = "The {race} of Narache thank you, {name}. You show much promise." } })
apply(748, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Tatzen und die Krallen, {name}?", completion = "Das habt Ihr gut gemacht, {name}. Ich werde ihre Macht jetzt an ein Totem der Säuberung binden." }, enUS = { progress = "Do you have the paws and talons, {name}?", completion = "You have done well, {name}.  I will take these and bind their power into a totem of cleansing." } })
apply(749, { "classic", "forever" }, { deDE = { completion = "Die Kiste ist auf allen Seiten mit dem Zeichen der Bergbaugesellschaft Venture Company versehen. Die sorgfältig auf eine Seite des Kartons gedruckten Notizen geben an, dass der Inhalt zur Weiterverarbeitung in einer ihrer zentralen Fabriken gedacht ist." }, enUS = { completion = "All sides of the crate are stamped with the sign of the Venture Co. Mining Division. Notes printed carefully on the side of the carton indicate that the contents are due for processing at one of their central plants." } })
apply(750, { "classic", "forever" }, { deDE = { progress = "Wenn Ihr für den Stamm Pelze besorgt, werde ich meinem Vater, Häuptling Hawkwind, von Euren großzügigen Taten berichten.", completion = "Die {race} von Narache danken Euch, {name}. Eines Tages wird man Euch in Thunder Bluff bestimmt wegen Eurer Jagdfertigkeiten verehren." }, enUS = { progress = "If you can provide pelts for the tribe I will pass word along to my father, Chief Hawkwind, of your generous deeds.", completion = "The {race} of Narache thank you for these provisions, {name}. With your skill in the ways of the hunt you will surely be revered in Thunder Bluff someday." } })
apply(751, { "classic", "forever" }, { deDE = { progress = "Grüße, {name}. Habt Ihr etwas Neues über die Pläne und Vorhaben der Venture Company in unserer Heimat erfahren?\n\nWenn sie vorhaben, unser Land so wie andere davor auszuplündern, werden die Kundschafter dem schnellstens ein Ende setzen.", completion = "Es scheint wirklich so, als wollte die Venture Company versuchen, unsere natürlichen Rohstoffe zu rauben. Gut, dass wir es endgültig wissen, und jetzt müssen wir wohl etwas dagegen unternehmen." }, enUS = { progress = "Hail, {name}. Have you learned anything new about the Venture Co.'s plans and operations in our homeland?\n\nIf they plan to exploit our lands as they have others, the Outrunners will be quick to put an end to it.", completion = "It does indeed appear that the Venture Co. is attempting to rob us of our natural resources. It is good to know this for true, and now it seems, we must do something about it." } })
apply(752, { "classic", "forever" }, { deDE = { completion = "Ihr seid so weit gereist, nur um einer alten Frau zu helfen? So, so, Ihr glaubt, ich brauche einen Bewahrer?" }, enUS = { completion = "You traveled all this way just to help an old woman? My my, aren't you a keeper?" } })
apply(753, { "classic", "forever" }, { deDE = { progress = "Ihr seht aus, als wärt Ihr gerade erst aus den Ebenen zurückgekehrt. Habt Ihr etwas von Großmutter Hawkwind gehört?", completion = "Ihr habt diese Kanne wohl auf Großmutters Bitte hin zurückgetragen.\n\nEure Bereitschaft anderen zu helfen und für die {race} im Camp Narache zu sorgen, lässt mich glauben, dass die {race} in Thunder Bluff eines Tages stolz auf Euch sein können." }, enUS = { progress = "You look as though you have returned from the plains. Do you have any word from Greatmother Hawkwind?", completion = "You carried this pitcher back at the Greatmother's bidding, I see.\n\nYour willingness to help others and provide for the {race} of Camp Narache leads me to believe you would make the tribe proud in Thunder Bluff someday." } })
apply(754, { "classic", "forever" }, { deDE = { progress = "Schiebt es nicht auf, {name}. Die Besudelung des Winterhoof-Brunnens muss beseitigt werden!", completion = "Die Nachricht von Eurer Tat hat mich soeben erreicht - die Tiere im Umkreis des Brunnens trinken bereits wieder gierig daraus.\n\nIhr habt dem Land einen großen Dienst erwiesen, {name}. Und Ihr habt dem Volk der {race} einen großen Dienst erwiesen." }, enUS = { progress = "Do not delay, {name}.  The Winterhoof Well's taint must be removed!", completion = "News of your deed reached me moments ago -- already the beasts near the well drink from it eagerly.\n\nYou have done a great thing for the land, {name}.  And you have done a great thing for the {race} people." } })
apply(755, { "classic", "forever" }, { deDE = { completion = "Häuptling Hawkwind hat Euch geschickt? Die Riten der Erdenmutter zu bestehen ist keine leichte Aufgabe..." }, enUS = { completion = "Chief Hawkwind sent you? Embarking on the Rites of the Earthmother is no small task..." } })
apply(756, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Klauen, um die ich bat, {name}? Die Besudelung des Wasserbrunnens von Thunderhorn nimmt stündlich zu!", completion = "Danke, {name}. Die Reinheit, mit der diese Wildtiere jagen, ist für die Schaffung des nächsten Säuberungstotems äußerst wichtig.\n\nDie Goblins werden niemals lernen, dass es einen Unterschied macht, ob man das Land bekämpft oder ob man im Einklang mit ihm lebt." }, enUS = { progress = "{name}, do you have the claws I sent you to gather?  The Thunderhorn Water Well grows more tainted with each passing hour!", completion = "Thank you, {name}.  The purity with which these beasts hunt is vital in the creation of the next cleansing totem.\n\nThe goblins will never learn the difference between contending with the land, and living in harmony with it." } })
apply(757, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Ritus der Kraft schon absolviert, {name}? Ich verlange einen Beweis für Euren Wagemut gegenüber den Feinden unseres Stammes, den Borstennacken.", completion = "Ihr habt die erste Prüfung der Riten der Erdenmutter bestanden. Der Stamm wird stolz auf Euch sein." }, enUS = { progress = "Have you completed the Rite of Strength, {name}? I require proof of your valor against the enemy of our tribe, the Bristlebacks.", completion = "You have passed the first test of the Rites of the Earthmother. The tribe will be proud." } })
apply(758, { "classic", "forever" }, { deDE = { progress = "Der Wasserbrunnen von Thunderhorn ist immer noch besudelt, {name}. Bitte, Ihr müsst das Ritual durchführen!", completion = "Die Vorfahren des Thunderhornklans haben in einem Traum zu mir gesprochen und Eure Handlungen in der Nähe ihres Brunnens gepriesen.\n\nSie möchten hiermit ihrer Dankbarkeit Ausdruck verleihen..." }, enUS = { progress = "The Thunderhorn Water Well is still tainted, {name}.  Please, you must perform the ritual!", completion = "Ancestors of the Thunderhorn clan spoke to me in a dream, praising you for your actions near their well.\n\nFor their gratitude, they wish to give you this..." } })
apply(759, { "classic", "forever" }, { deDE = { progress = "{name}. Habt Ihr die Zähne, um die ich gebeten habe?", completion = "Sehr gut, {name}. Ich kann das Opfer fühlen, das das Land gebracht hat, und mein Geist ist erfüllt von Traurigkeit und Stolz." }, enUS = { progress = "{name}.  Do you have the teeth I asked for?", completion = "Very good, {name}.  I can feel the sacrifice of the land in this offering, and my spirit swells with sadness, and pride." } })
apply(760, { "classic", "forever" }, { deDE = { completion = "Ihr habt es geschafft. Ihr habt die Brunnen gesäubert und unser Land geheilt. Ganz Bloodhoof dankt Euch, {name}.\n\nMöge der Wind Kunde von Euren Taten in alle Welt tragen und mögen die Wasser von Mulgore bis in alle Ewigkeit rein sein." }, enUS = { completion = "You've done it.  You have cleaned the wells, and healed our land.  Bloodhoof village is grateful, {name}.\n\nMay the wind whisper your deeds for a hundred seasons, and may the waters of Mulgore remain clean forever." } })
apply(761, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Sturzflieger gefunden, {name}? Habt Ihr ihre Federkiele?", completion = "Ich weiß, dass es nicht leicht war, an diese Federkiele heranzukommen, {name}. Ihr habt damit bewiesen, dass Ihr ein würdiger {class} seid. Es ist gut, Euch hier in Bloodhoof zu haben." }, enUS = { progress = "Have you found the swoops, {name}.  Do you have their quills?", completion = "I know that gathering these quills was not an easy task, {name}.  In doing this, you prove that you are a {class} of merit.  It is good to have you at Bloodhoof Village." } })
apply(762, { "classic", "forever" }, { deDE = { progress = "Zeit ist hier entscheidend, {name}. Ragnaros wird nicht abwarten, bis wir uns vorbereitet haben.", completion = "{name}, es besteht kein Zweifel an Eurem Engagement für Ironforge und das Volk der Zwerge. Ich danke Euch für Eure Hilfe in dieser Angelegenheit.\n\nIch werde den Historiker Karnik wissen lassen, dass Ihr Erfolg hattet, und ich werde auch veranlassen, dass so bald wie möglich Hilfe ins Ödland geschickt wird, um die Ausgrabungsstätte zurückzuerobern. Nochmals danke.\n\nBevor Ihr geht, habe ich jedoch noch eine Bitte im Namen von König Bronzebeard an Euch." }, enUS = { progress = "Time is of the essence, {name}. Ragnaros will not wait for us to prepare.", completion = "{name}, your dedication to Ironforge and to the dwarven people cannot be refuted. I thank you for your help in this matter.\n\nI shall send word to Historian Karnik informing him that you have succeeded, and I shall also have aid sent to the Badlands as soon as possible to help recover the excavation site. Thank you again.\n\nBefore you go, there is one more thing I would ask of you in the name of King Bronzebeard." } })
apply(763, { "classic", "forever" }, { deDE = { progress = "Was führt Euch in mein Dorf, {class}?", completion = "Eine Nachricht von meinem guten Freund Häuptling Hawkwind! Ah, seine Schnitzereien sagen mir, dass Ihr von besonderer Art seid." }, enUS = { progress = "What brings you to my village, {class}?", completion = "Word from my good friend, Chief Hawkwind! Ah, I can see by his carvings you are of a special breed." } })
apply(764, { "classic", "forever" }, { deDE = { progress = "Der Venture Company wurden die Bergbaurechte hier in Mulgore verweigert, aber es scheint so, als würde sie ein Nein als Antwort nicht akzeptieren. Wir {race} neigen jedoch nicht zu Haarspaltereien und wir haben andere Wege, unsere Nachricht klar rüberzubringen.", completion = "Ich glaube nicht, dass man dieses Signal fehldeuten oder ignorieren kann, oder? Die Venture Company wird die {race} nicht mehr auf die leichte Schulter nehmen oder so arrogant sein zu glauben, dass wir ihren Diebstahl der natürlichen Rohstoffe um uns herum einfach so widerstandslos hinnehmen." }, enUS = { progress = "The Venture Co. was refused mining rights here in Mulgore, but it would seem that they do not take no for an answer. We {race} are not ones to mince words, however, and we have other ways of getting our message across.", completion = "I don't think there could be too much misinterpreting or ignoring of that signal, hm? The Venture Co. will know not to take the {race} lightly, or to be so arrogant as to believe we would allow them to steal the natural resources around us without protest." } })
apply(765, { "classic", "forever" }, { deDE = { progress = "Ich koche vor Wut, wenn ich an all die Gräueltaten denke, die die Venture Company um des Profits Willen an uns begehen würde.", completion = "Die Nachricht vom Tod des Bösewichts Fizsprocket hat meine Wut etwas abgekühlt. Ich werde seine persönlichen Habseligkeiten durchsehen, um herauszufinden, ob es weitere Informationen über die Zukunftspläne der Venture Company gibt. Vielen Dank für Eure Bemühungen, {name}." }, enUS = { progress = "I seethe with anger at the thought of the atrocities the Venture Co. is willing to perpetrate against us in the name of profit.", completion = "My anger is somewhat lessened at the news that the villain Fizsprocket is dead. I will go through his personal effects and see if there is any additional information about what the Venture Co. has planned for the future. Thank you for your efforts, {name}." } })
apply(766, { "classic", "forever" }, { deDE = { progress = "Mein Fieber wird immer schlimmer und ich merke, wie ich langsam in schreckliche Alpträume abgleite... Ich hätte wissen müssen, dass ich keine Bestie bewältigen kann, die selbst mein Großvater nicht besiegen konnte...\n\nHabt Ihr die Zutaten für die Arznei? Ich fürchte, wenn ich die Infektion nicht bald säubere, wird das mein Ende sein.", completion = "Ah, danke, {name}. Mit den Dingen, die Ihr mir gebracht habt, kann ich die Arznei herstellen, mit der ich die Ausbreitung der Infektion unterbinden und die Krankheit endgültig heilen kann. Ich schulde Euch meinen lebenslangen Dank.\n\nAber ich werde nie diesen schrillen Schrei vergessen, als sich Mazzranache auf mich stürzte, diese Explosion von Farben, als sich sein Schnabel senkte ...\n\nSeid vorsichtig auf Euren Reisen." }, enUS = { progress = "My fever grows worse and I find my mind drifting into delirious nightmares... I should have known that I wouldn't be able to handle a beast my grandfather was unable to defeat...\n\nDo you have the ingredients for the remedy? I fear if I do not clean the infection soon, it will be the death of me.", completion = "Ah, thank you, {name}. Using the items you brought me, I will be able to create the remedy I need to stop the spread of the infection and, eventually, cure it completely. I owe you my life in thanks.\n\nBut I'll never forget that screeching call when Mazzranache came upon me, the blaze of color as its beak descended...\n\nBe wary on your travels." } })
apply(767, { "classic", "forever" }, { deDE = { completion = "Ich wusste, dass Ihr mich aufsuchen würdet, {class}. Ich erkenne immer, wenn jemand versuchen möchte, die Riten der Erdenmutter zu bestehen." }, enUS = { completion = "I sensed you would be coming to me, {class}. I can always recognize one who is trying to pass the Rites of the Earthmother." } })
apply(768, { "classic", "forever" }, { deDE = { progress = "Hallo. Wart Ihr auf der Jagd? Habt Ihr Häute für mich?", completion = "Ah, das sind aber besonders hübsche Stücke. Daraus kann ich feine Lederwaren herstellen.\n\nHier, {name}. Nehmt das dafür..." }, enUS = { progress = "Hello again.  Have you been hunting?  Do you have skins for me?", completion = "Ah, these are very nice pieces.  They'll make fine leather goods.\n\nHere, {name}.  Take this in trade..." } })
apply(769, { "classic", "forever" }, { deDE = { progress = "Habt Ihr meine Materialien, {name}?", completion = "Ah, gut. Danke, {name}. Mein Herz springt vor Stolz, dass Ihr so am Lederverarbeitungshandwerk interessiert seid." }, enUS = { progress = "Do you have my supplies, {name}?", completion = "Ah, good.  Thank you, {name}.  My heart swells with pride to see youths interested in the craft of leatherworking." } })
apply(771, { "classic", "forever" }, { deDE = { progress = "Sobald Ihr genügend Quellsteine bei den Wasserbrunnen und Bernsteinkörner unter den Bäumen gesammelt habt, bereite ich das Wasser der Seher für Euch zu.", completion = "Wie ich sehe, habt Ihr das Sammeln von unserem heiligen Land gelernt, {name}. Es wird nur einen Augenblick dauern, bis ich das Wasser der Seher gebraut habe." }, enUS = { progress = "Once you have gathered enough well stones from around the water wells and Ambercorn from beneath the trees, I will prepare the Water of the Seers for you.", completion = "I see you have learned to gather from our sacred land, {name}. It will take but a moment for me to brew the Water of the Seers." } })
apply(773, { "classic", "forever" }, { deDE = { completion = "Ihr habt in Eurem Verlangen, die Riten der Erdenmutter zu bestehen, großen Eifer erkennen lassen, {name}.\n\nWir, die Vorfahrengeister, repräsentieren die mächtigen {race}, die mutig ihr Leben gaben, um das Fundament unserer großen Stadt Thunder Bluff zu legen und zu beschützen. Hiermit gebe ich die Pflicht des Schutzes an Euch weiter.\n\nIhr habt den Ritus der Weisheit bestanden, {class}. Betretet Thunder Bluff mit Stolz." }, enUS = { completion = "You have shown great diligence in your yearning to pass the Rites of the Earthmother, {name}.\n\nWe, the Ancestral Spirits, represent the mighty {race} who gave their lives bravely to found and protect our great city of Thunder Bluff. I hereby pass the duty of that protection over to you.\n\nYou have passed the Rite of Wisdom, young {class}. Enter Thunder Bluff with pride." } })
apply(775, { "classic", "forever" }, { deDE = { completion = "Grüße, {class}. Wie ich sehe, habt Ihr den Weg zu meiner Türschwelle gefunden." }, enUS = { completion = "Hail, young {class}. I see you found your way to my doorstep." } })
apply(776, { "classic", "forever" }, { deDE = { progress = "Seid Ihr Arra'chea schon auf der Spur?", completion = "Gut gemacht! Das ist ein feines Jagdergebnis.\n\nIch werde einen Sammeltrupp losschicken, der den Kadaver holt, damit wir Balg und Fleisch bergen können.\n\nIhr habt unserem Volk einen großen Dienst erwiesen, {name}." }, enUS = { progress = "Have you tracked down Arra'chea yet?", completion = "Well done! A fine kill that was.\n\nI will send a gathering party to collect the carcass so we can retrieve the hide and meat.\n\nYou have done a great deed for your people, {name}." } })
apply(777, { "classic", "forever" }, { deDE = { progress = "<Ohne von seinen Fesseln aufzusehen, streckt Lotwil seine Hand aus, seine Finger zucken ungeduldig.>\n\nDas Zahnrad, {name}, das Zahnrad!", completion = "Ah, perfekt. Tretet zurück und seht, wie ich Geschichte schreibe!\n\n<Lotwil setzt fieberhaft seine Arbeit fort.>" }, enUS = { progress = "<Without looking up from the shackles, Lotwil holds out a hand and waggles his fingers impatiently.>\n\nThe cog, {name}, the cog!", completion = "Ah, perfect. Stand back while I prepare to make more history!\n\n<Lotwil continues to work feverishly.>" } })
apply(778, { "classic", "forever" }, { deDE = { progress = "Mit diesem Resultat hatte ich eigentlich nicht gerechnet. Würdet Ihr mir wohl meine Fesseln zurückbringen?", completion = "Danke, {name}. Das war wirklich eine Feuerprobe, nicht wahr?\n\nIch bin mir nicht sicher, was da schief gegangen sein könnte. Nur gut, dass meine Magie die Kreatur wieder in ihre Heimatebene zurückschicken konnte.\n\nEin kleines Zeichen meiner Anerkennung all Eurer harten Arbeit ..." }, enUS = { progress = "Not quite the outcome I was expecting. Could you get my shackles back?", completion = "Thank you, {name}. That was quite an ordeal, wasn't it?\n\nI'm not sure what could have gone wrong. It was a good thing my magics were here to help send the creature back to its home plane.\n\nPerhaps a little token of appreciation for all your hard work..." } })
apply(780, { "classic", "forever" }, { deDE = { progress = "Die Aggressivität der Kampfeber nimmt weiter zu. Habt Ihr ihnen einen deutlichen Warnschuss verpasst und mir ein paar Schnauzen und Flanken mitgebracht?", completion = "Sehr eindrucksvoll. Diese Zutaten werden einen feinen Eintopf ergeben und der Verlust dieser Eber sollte für die elenden Borstennacken eine ordentliche Lektion sein." }, enUS = { progress = "The aggression of the Battleboars is increasing. Have you sent them a clear message and brought back some snouts and flanks yet?", completion = "Most excellent. These ingredients will make a fine stew and the loss of those boars should be a fair lesson to those vile Bristlebacks." } })
apply(781, { "classic", "forever" }, { deDE = { progress = "Ihr seht besorgt aus, {name}. Welche Neuigkeiten bringt Ihr?", completion = "Das ist in der Tat sehr beunruhigend! Aber durch diese Informationen können wir all unsere Brüder in Bloodhoof aufrufen, uns bei der Abwehr des Angriffs zu helfen. Ihr habt das Leben vieler {race} gerettet, {name}." }, enUS = { progress = "You have a look of concern about you, {name}. What news do you bring?", completion = "This is quite alarming indeed! But with this information we can call on our brethren from Bloodhoof Village to help thwart the attack. You have saved the lives of many {race}, {name}." } })
apply(782, { "classic", "forever" }, { deDE = { progress = "Tho'gruns Verrat... wen wundert es da noch, dass die Oger nicht mehr der Horde angehören? Ich bin froh, dass er tot und das Zeichen der Erde wieder da ist.\n\nFalls Ihr ihn noch erledigt habt, dann verschwendet keine Zeit und geht zum Camp Boff. Es befindet sich südöstlich von Kargath.", completion = "Tho'grun ist tot, seine Leiche blank genagt von den Wüstenwinden und Aas fressenden Bussarden und die Oger sind demoralisiert. Es ist zwar nur ein kleiner Sieg, aber er wird zu einem größeren führen.\n\nDas Zeichen der Erde befindet sich jetzt in unserem Besitz und wir können das Gefängnis der Schwarzdrachen in Lethlor öffnen. Wir werden sie aus einer endlosen Gefangenschaft befreien, ungeachtet ihres Verdammnisses!" }, enUS = { progress = "Tho'grun's betrayal... is there any wonder why the ogres are part of the Horde no longer? I will be glad to see him dead, and the Sign of the Earth returned.\n\nIf you've not dispatched him yet, then waste no time going to Camp Boff.  It is to the southeast of Kargath.", completion = "With Tho'grun dead, his corpse picked clean by the desert winds and scavenging buzzards, the ogres will be put into disarray. Though a small victory, this will lead to a much larger one\n\nThe Sign of the Earth is now in our possession, and we can open the black drakes' prison in Lethlor.  We shall free them from endless imprisonment, albeit to their doom!" } })
apply(783, { "classic", "forever" }, { deDE = { completion = "Ah, gut. Noch ein Freiwilliger. Es kommen viele davon in letzter Zeit.\n\nHoffentlich sind es genug.\n\nDas Menschenland wird von außerhalb bedroht und große Teile unserer Streitkräfte wurden ins Ausland beordert. Das lässt Raum für verderbte und gesetzlose Gruppen, die sich innerhalb unserer Grenzen ausbreiten können.\n\nWir kämpfen hier gleich an mehreren Fronten, {name}. Stellt Euch auf eine lange Kampagne ein." }, enUS = { completion = "Ah, good.  Another volunteer.  We're getting a lot of you these days.\n\nI hope it's enough.\n\nThe {race} lands are threatened from without, and so many of our forces have been marshaled abroad.  This, in turn, leaves room for corrupt and lawless groups to thrive within our borders.\n\nIt is a many-fronted battle we wage, {name}.  Gird yourself for a long campaign." } })
apply(784, { "classic", "forever" }, { deDE = { progress = "Ihr habt Eure Befehle, {name}. Die Sicherheit Durotars ist in Gefahr. Erledigt die vor Euch liegende Aufgabe oder lasst aus Scham den Kopf hängen.\n\nZeigt, dass Ihr Ehre besitzt, und besiegt die Menschen auf Burg Tiragarde.", completion = "Die Kunde über Euren Mut verbreitet sich schnell, {class}. In Orgrimmar wird man noch lange die Legende Eures Sieges auf Burg Tiragarde erzählen." }, enUS = { progress = "You have your orders, {name}. The safety of Durotar is in question. Complete the task before you or hang your head in shame.\n\nShow your honor and defeat the humans of Tiragarde Keep.", completion = "Word of your bravery travels fast, {class}. Tales of your victory at Tiragarde Keep will be heralded in Orgrimmar." } })
apply(786, { "classic", "forever" }, { deDE = { progress = "Die Zentauren haben bewiesen, dass sie für die Horde eine andauernde Plage darstellen. Ihre Absichten, unsere Heimat zu belagern, dürfen nicht einfach so hingenommen werden.", completion = "Die Horde würde einen Angriff der Kolkarzentauren sicherlich überstehen. Aber wenn wir einen solchen Angriff verhindern, ersparen wir unnötiges Blutvergießen unter unseren mächtigen Kriegern.\n\nUnd so sicher wie es Sand in der Wüste von Tanaris gibt, wissen wir, dass Blut vergossen werden wird, bevor diese schwierigen Zeiten hinter uns liegen.\n\nIhr habt unserem Volk gut gedient, {class}." }, enUS = { progress = "The centaurs have proven to be a consistent nuisance to the Horde. Their intentions to lay siege to our homeland cannot be tolerated.", completion = "The Horde would surely prevail if the Kolkar centaurs were to attack. But by preventing such an attack, we have spared our mighty warriors unnecessary bloodshed.\n\nAnd as sure as there is sand in the Tanaris desert, we know that there will be blood spilled before these trying times are through.\n\nYou have served your people well, {class}." } })
apply(788, { "classic", "forever" }, { deDE = { completion = "Hmmm, nicht schlecht, {name}. Aber bildet Euch nur nichts darauf ein... Ihr werdet in Eurem Leben noch gegen ganz andere Gegner als Eber kämpfen müssen.\n\nWie dem auch sei, Ihr habt Euch gut gehalten und Eure nächste Aufgabe wird es sein, einen erheblich gefährlicheren Gegner zu bekämpfen, also braucht Ihr etwas zusätzlichen Schutz." }, enUS = { completion = "Hmmm, not bad, {name}. But don't let it get to your head...you'll fight tougher than boars in your career.\n\nNonetheless, you've proven yourself well, and your next trial will be against a considerably more dangerous opponent, so you'll need some extra protection." } })
apply(789, { "classic", "forever" }, { deDE = { progress = "Der Knochenpanzer eines Skorpiden ist nicht so dick, dass sich ein kräftiger und entschlossener Krieger davon abschrecken lässt. Schlagt fest und ohne Zögern zu, dann sollten sich die Skorpide als leichte Beute erweisen.", completion = "Es gibt eine wichtige Lektion, die Ihr bei Euren Kämpfen gegen Skorpide gelernt haben solltet. Nicht nur die größten, sondern auch die kleinsten Gegner können Euch zum Verhängnis werden. In einem erbitterten Kampf kann Euch alles Mögliche das Genick brechen.\n\nIch kann Euch nichts weiter beibringen, {name}. Ihr habt Euch sehr gut entwickelt und ich werde Eure Fortschritte mit Interesse verfolgen." }, enUS = { progress = "The carapace of a scorpid isn't so thick that the strength of a determined warrior will be deterred. Strike strongly and without doubt, and the scorpids should prove easy prey.", completion = "There is an important lesson that you must take away from fighting scorpids. The smallest or largest of opponents can still send you to your doom. In fierce combat, any number of things can prove your downfall.\n\nI have no more to teach you, {name}. You have done well, and I will watch your progress with interest." } })
apply(790, { "classic", "forever" }, { deDE = { progress = "Ah... mein Vater sagte immer, aus mir würde nie etwas werden. Ich fürchte, so, wie ich hier unter dem Baum liege, während mein Leben mir zwischen den Fingern zerrinnt, sieht es aus, als hätte er Recht gehabt.\n\nIch wünsche mir nur, mit dem Wissen sterben zu können, dass mein letzter Feind in diesem Leben tot ist.", completion = "Mein Schlag war nicht stark genug, um ihn zu töten, aber wenn ich mir den Schaden ansehe, den ich verursacht habe, macht es mich doch ein bisschen stolz. Mit diesem bisschen Stolz muss ich mich zufrieden geben, wenn ich sterbe; doch in diesem Licht betrachtet, erfüllt mich die kurze Liste meiner im Leben erreichten Leistungen mit Wut." }, enUS = { progress = "Ahhh... my father always said I would never amount to much, and here, lying beneath a tree as life seeps away, I'm afraid it looks like he was right.\n\nAt least I wish to die knowing that my last enemy in life lays dead.", completion = "My blow was not enough to kill him, but looking at the damage I inflicted gives me some small measure of pride. That small measure will be all I have to sustain myself if I die, and in that light, the short list of my life's accomplishments fills me with anger." } })
apply(791, { "classic", "forever" }, { deDE = { progress = "Als wir in diesem Land Pionierarbeit leisteten, kämpfte ich stolz an der Seite des Kriegshäuptlings. Meine Haut ist mit Narben von Kämpfen übersät.\n\nDie Ehre der Horde wurde durch meine Axt und meinen Kampfschrei während des Besiegens von Archimonde gefestigt, als die unheilige Allianz mit den Menschen und Elfen aus der Not heraus geschlossen wurde.\n\nAber meine Stellung als Wachmann und Versorger hat meinem Leben einen neuen Sinn gegeben.", completion = "Ausgezeichnet, {name}. Jeder gute {class} wird für diese Tasche auf dem Schlachtfeld eine Verwendung finden.\n\nIch salutiere vor Eurer Schlagkraft und Bereitschaft, im Namen der Horde zu sterben!" }, enUS = { progress = "I fought proudly alongside the Warchief when these lands were pioneered. The scars of battle mark my skin.\n\nThe honor of the Horde has been upheld with the help of my axe and battlecry during the defeat of Archimonde, when the unholy alliance was made with the humans and elves, wrought from necessity.\n\nBut my position as watchman and provider has given me a new sense of worth.", completion = "Most excellent, {name}. Any good {class} will surely find a use for this bag on the battlefield.\n\nI salute your vigor and willingness to die in the name of the Horde!" } })
apply(792, { "classic", "forever" }, { deDE = { completion = "Das habt Ihr gut gemacht, {name}.\n\nDie elenden Familiare waren zwar nur Schoßtiere der dunkleren Mächte der Burning Blade, aber Euer Sieg über sie lässt mich ahnen, dass noch größere Taten folgen werden." }, enUS = { completion = "You have done well, {name}.\n\nAlthough the Vile Familiars were merely pets of the darker powers within the Burning Blade, your success against them foretells greater deeds ahead." } })
apply(793, { "classic", "forever" }, { deDE = { progress = "Es gibt nur wenige Feinde, die tödlicher als Großdrachen sind, und es gab nur wenige Großdrachen, die so unerbittlich kämpften wie Schattenbringer und Hematus.", completion = "Der schwarze Drachenschwarm ist weiter mit den abtrünnigen Orcs der Blackrock verbündet, und beide müssen entweder zur Einsicht gebracht oder ausgelöscht werden. Da Schattenbringer und Hematus tot sind, können wir unsere Aufmerksamkeit westwärts auf die Blackrockspitze richten." }, enUS = { progress = "There are few enemies more deadly than dragonkind, and there were few dragons that fought as ferociously as Blacklash and Hematus.", completion = "The black dragonflight continues to ally with the renegade Blackrock orcs, and both must be brought into line, or removed. With Blacklash and Hematus dead, we can turn our attentions westwards, towards Blackrock Spire." } })
apply(794, { "classic", "forever" }, { deDE = { progress = "Ist Euer Auftrag beendet, {name}? Habt Ihr das Medaillon der Burning Blade?", completion = "Ihr habt es! Gut gemacht!\n\nEure Bemühungen im Koven der Burning Blade sind der Schlüssel für die Ausrottung dieses Kults im Tal der Prüfungen. Ich fürchte jedoch, dass sie in unserem Land noch mehr vorhaben.\n\nNoch sind wir sie nicht endgültig los." }, enUS = { progress = "Is your task complete, {name}?  Do you have the Burning Blade Medallion?", completion = "You retrieved it!  Well done!\n\nYour efforts within the Burning Blade Coven are key in rooting out this cult in the Valley of Trials.  But I fear they have further aims in our land.\n\nWe have not seen the end of them." } })
apply(804, { "classic", "forever" }, { deDE = { completion = "Eurer Beschreibung der Bestie nach bin ich mir sicher, dass es sich um Sarkoth handelt! Kein Wunder, dass Hana'zua damit überfordert war. Wir werden ihm sofort Hilfe schicken, also macht Euch keine Gedanken mehr um Hana'zuas Notlage.\n\nIch muss jedoch sagen, dass ich zutiefst beeindruckt bin zu hören, dass Ihr Sarkoth besiegt habt. Das ist eine Leistung, auf die Ihr stolz sein könnt, {name}. Und dass Ihr für die Ehre eines Fremden kämpft, obwohl Ihr doch mit anderen Dingen beschäftigt seid, trägt nur zu Eurer eigenen Ehre bei." }, enUS = { completion = "From your description of the beast, I believe you must be speaking of Sarkoth! It is no wonder that Hana'zua was overtaken by it. Aid will be dispatched to him immediately, trouble yourself no more with Hana'zua's plight.\n\nHowever, I must say, I am most impressed to hear that you brought Sarkoth to death. It is a feat to be proud of, {name}. And that you would fight for a stranger's honor, while other tasks occupied your time, your own honor is heightened." } })
apply(805, { "classic", "forever" }, { deDE = { completion = "Hm... Euer Bericht kommt zu einem schlechten Zeitpunkt. Die Burning Blade wurden hier in Sen'jin noch nicht gesehen, aber das Böse ist vor der Küste auf den Echoinseln auf fruchtbaren Boden gefallen.\n\nDie Orcs sind Freunde der Darkspeartrolle. Ehrenhafte Freunde. Wir wollen den Orcs helfen, aber... wir benötigen ebenfalls Hilfe." }, enUS = { completion = "Hm... your report comes at a bad time.  The Burning Blade is not seen here in Sen'jin, but their evil has taken seed off the coast, on the Echo Isles.\n\nThe orcs are friends of the Darkspear Trolls.  Honorable friends.  We want to help the orcs, but... we need help too." } })
apply(806, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Fizzle gefunden, {name}? Er und der Rest der Burning Blade müssen von unserem Land vertrieben werden!", completion = "Aha! Ihr habt ihn!\n\nIhr macht Eurem Klan alle Ehre, {name}. Und dank Euch ist Durotar jetzt von einem weiteren Agenten des Bösen befreit." }, enUS = { progress = "Did you find Fizzle, {name}?  He, and rest of the Burning Blade, must be scoured from our lands!", completion = "Aha!  You got him!\n\nYou do your clan proud, {name}.  And because of you, Durotar is free of one more agent of evil." } })
apply(808, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Schädel meines Bruders, {name}? Ist er endlich frei?", completion = "Danke, {name}. Ihr habt Minshina gerettet. Ihr habt den Geist meines Bruders aus der Sklaverei befreit!" }, enUS = { progress = "Do you have my brother's skull, {name}?  Is he finally free?", completion = "Thank you, {name}.  You have saved Minshina.  You have saved my brother's spirit from slavery!" } })
apply(809, { "classic", "forever" }, { deDE = { completion = "Neeru wünscht also, dass die Dämonensaat zerstört wird? Seltsam...\n\nWohlan denn. Wenn er möchte, dass die Saat verschwindet, dann werde ich Euch erklären, wie man sie entfernt." }, enUS = { completion = "Neeru wants the Demon Seed destroyed, does he?  Strange...\n\nVery well.  If he wishes the seed gone, then I will tell you how to remove it." } })
apply(812, { "classic", "forever" }, { deDE = { progress = "Ich bin fast froh, dass ich in meinem jetzigen Zustand nicht nach Sen'jin zurückkehren kann. Man würde dort sicherlich über meine Schwäche und Dummheit spotten.", completion = "{name}, Ihr habt mir das Leben gerettet. Danke.\n\nBitte nehmt das hier; ich hoffe, es kann Euch auf Euren Reisen behilflich sein, wenn nicht sogar ein bisschen Geld einbringen. Wie Ihr sagtet, werde ich es wohl in nächster Zeit nicht benötigen. Kor'ghan wird mir noch weitere seiner Rituale auferlegen, bevor ich mich bewiesen habe. Noch mehr Eber töten, noch mehr Skorpidschwänze sammeln..." }, enUS = { progress = "I'm almost glad I can't return to Sen'jin as I am now. My weakness and stupidity would surely be mocked.", completion = "{name}, you've saved my life. Thank you.\n\nPlease take this; I hope it can at least help you in your travels, if not bring you some coin. From what you say, I won't be usin' it anytime soon. Kor'ghan is gonna march me through more of his rituals until I prove myself. More killin' boars, more gatherin' scorpid tails..." } })
apply(813, { "classic", "forever" }, { deDE = { progress = "Denkt daran, es spielt keine Rolle, welche Kreatur Ihr jagt, aber Ihr tätet gut daran, sie vorher zu studieren und ihre Verhaltensweisen zu kennen. Dieses Wissen könnte Euch das Leben retten.", completion = "Hier habt Ihr das Gegengift, {name}. Bringt es so schnell wie möglich Rhinag und seid vorsichtig." }, enUS = { progress = "Remember, no matter what creature you hunt, you would do well to study it and understand its behavior. That knowledge could save your life.", completion = "Here is the antidote, {name}. Take it to Rhinag as soon as you can, and be cautious." } })
apply(815, { "classic", "forever" }, { deDE = { progress = "Frühstück, Mittagessen, Abendbrot! Wen kümmert's schon, welche Mahlzeit dran ist? Sie müssen trotzdem von jemandem zubereitet werden - und dieser Jemand bin ich!", completion = "Ihr mögt zwar schwach sein, aber wenigstens seid Ihr nicht ungeschickt, {name}.\n\nHier, nehmt das und verschwindet. Ich muss Essen machen." }, enUS = { progress = "Breakfast, lunch, dinner! Who cares which meal it is? It still has to be cooked by someone--namely me!", completion = "You might be weak, but at least you're not clumsy, {name}.\n\nHere, take this and get outta my way. I've got cooking to do." } })
apply(816, { "classic", "forever" }, { deDE = { progress = "Ich bete, dass Kron zu mir zurückkehrt, aber ich bin mir fast sicher, dass ich weiß, was mit ihm geschehen ist.", completion = "Oh, mein Sohn... mein wunderbarer Sohn.\n\nDie Ungewissheit über das Schicksal meines Sohns hat mich gequält, seit er weggegangen ist. Da ich jetzt weiß, was mit ihm geschehen ist, kann ich vielleicht endlich beginnen zu trauern.\n\nDanke, {name}. Bitte, nehmt dies hier. Ich wollte es Kron bei seiner erfolgreichen Rückkehr schenken. Ich weiß jetzt, dass er tot ist, und kann es nicht ertragen, es zu sehen." }, enUS = { progress = "I pray that Kron will return to me, but I'm almost certain I know his fate already.", completion = "Oh, my son... my beautiful son.\n\nUncertain of my son's fate, I have tormented myself since he left. Now that I know what's happened, perhaps I can finally begin to mourn.\n\nThank you, {name}. Please take this. I was going to give it to Kron as a gift when he returned successful. Now that I know he is dead, I cannot bear to look at it." } })
apply(817, { "classic", "forever" }, { deDE = { progress = "Ich erinnere mich noch an meine erste Tigerjagd, {name}. Ich hatte mich für die größte der Echoinseln entschieden, um dort zu jagen, und ich saß fast den ganzen Tag lang mucksmäuschenstill im Schatten der Bäume... beobachtete... wartete.\n\nMeine Muskeln waren gespannt und ich war bereit zuzuschlagen. Es war einer meiner größten Triumphe, als der Tiger endlich den Köder nahm.", completion = "Ich freue mich, {name}! Dank Eurer Hilfe wird unser Volk geschützt sein und in der kalten Jahreszeit nicht frieren müssen.\n\nDanke." }, enUS = { progress = "I remember my first tiger hunt, {name}. I chose to hunt on the largest of the Echo Isles, and I sat perfectly still in the shadows of its foliage for almost a full day... watching... waiting.\n\nMy muscles were taut, and I was ready to strike. It was one of my greatest victories when that tiger finally took the bait.", completion = "I am pleased, {name}. Because of your help, our people will be protected, and not go cold as the seasons change.\n\nThank you." } })
apply(818, { "classic", "forever" }, { deDE = { progress = "Zeit ist die wahre Prüfung Eurer Kraft und Eures Willens. Verliert Ihr die Geduld oder gebt der Schwäche nach, dann zeigt sich Euer wahres Ich.", completion = "Gut gemacht, junger Freund... wirklich sehr gut." }, enUS = { progress = "Time is the true test of your strength and will. Lose patience or give in to weakness, and your true self will be shown.", completion = "Well done, young one... well done indeed." } })
apply(819, { "classic", "forever" }, { deDE = { progress = "Ja?", completion = "Da brat mir doch einer...\n\nDas war eines von Chen Stormstouts Fässchen. Er reiste vor langer Zeit an Rexxars Seite. Ich habe schon seit Ewigkeiten nichts mehr von ihm gesehen oder gehört. Danke, dass Ihr es mir gebracht habt, {name}." }, enUS = { progress = "Yes?", completion = "Well, I'll be...\n\nThis was one of Chen Stormstout's kegs. He traveled with Rexxar a long time ago. I haven't seen or heard about him in a kodo's age. I appreciate you bringing this to me, {name}." } })
apply(821, { "classic", "forever" }, { deDE = { progress = "Wie läuft Eure Suche?", completion = "Haha... Ich hätte nie gedacht, dass ich noch mal etwas von diesem Zeug brauen würde.\n\nIhr habt nostalgische Gefühle in mir geweckt, {name}. Erinnert mich irgendwie an das letzte Mal, als ich Trogggebräu gebraut habe. Danke. Die Erinnerungen wärmen mich innerlich." }, enUS = { progress = "How's the search going?", completion = "Haha... I never thought I'd make more of this stuff ever again.\n\nYou've stirred in me a great sense of nostalgia, {name}. Kind of reminds me of the last time I made a batch of trogg brew. Thank you. The memories warm my stomach." } })
apply(822, { "classic", "forever" }, { deDE = { progress = "Strengt Ihr Euch bei der Suche der Zutaten auch richtig an, {name}?", completion = "Haha! Ich wusste, dass Ihr diesem Gebräu nicht widerstehen könntet. Kommt wieder, wenn Ihr noch etwas mehr davon möchtet, {name}. Bringt mir dann noch etwas von den Zutaten, die ich Euch holen ließ." }, enUS = { progress = "You working hard at finding those ingredients, {name}?", completion = "Haha! I knew you couldn't resist some of this brew. Come back again anytime you want some more, {name}. Just bring me more of the ingredients I had you collect." } })
apply(823, { "classic", "forever" }, { deDE = { completion = "Ja? Ihr habt etwas zu berichten? Nun dann, heraus damit!" }, enUS = { completion = "Yes?  You have something to report?  Well then, let's have it!" } })
apply(824, { "classic", "forever" }, { deDE = { progress = "Ah, hallo auch. Ich verbringe eine Menge Zeit damit, das Wasser - eigentlich alle Elemente - so intensiv zu studieren, dass ich manchmal nicht einmal die Leute um mich herum wahrnehme.\n\nKann ich Euch irgendwie helfen?", completion = "Diese Kugel... ist sehr beunruhigend. Viele der mächtigeren Elementare beziehen ihre Kraft und Energie aus solchen Gegenständen. Einen davon quasi intakt zu finden, ist eine Sache. Ihn dermaßen besudelt vorzufinden, eine ganz andere.\n\nIch werde dafür Sorge tragen, dass diese Kugel vom Irdenen Ring gründlich untersucht wird. Vielleicht können wir dieser Verderbnis der Elemente ein Ende bereiten. Bitte, nehmt dies zum Tausch dafür, dass Ihr die Aufmerksamkeit des Irdenen Rings auf diese Kugel gelenkt habt." }, enUS = { progress = "Ah, hello there.  I spend a great deal of time studying the water - all the elements really - so much so that sometimes I don't even notice people around me.\n\nIs there something I can help you with?", completion = "This globe... it is most disturbing.  Many of the more powerful elementals receive their power and energy through such devices.  To find one like this nearly intact is one thing - to find it so tainted is another.\n\nI will see that this globe is studied properly by the Earthen Ring.  Perhaps we can bring an end to this corruption of the elements.  Please - accept this as a fair exchange for bringing this globe to the attention of the Earthen Ring." } })
apply(825, { "classic", "forever" }, { deDE = { progress = "Sobald wir wissen, wie die Menschen ihre seltsamen Maschinen bedienen, haben wir eine bessere Chance, sie in zukünftigen Schlachten besiegen zu können.\n\nMit unserem neu gewonnenen Wissen wächst die Kraft der Horde.", completion = "Eure Bergungsmission war ein Erfolg, {class}. Ich werde dafür sorgen, dass diese Werkzeuge mit der nächsten Karawane nach Orgrimmar geschickt werden.\n\nSehr gut gemacht." }, enUS = { progress = "Once we learn how the humans operate their strange machinery, we will stand a greater chance of defeating them in future battles.\n\nWith our new gained knowledge, the Horde only stands to grow in strength.", completion = "Your recovery mission was a success, {class}. I will see to it that these tools get to Orgrimmar with the next caravan.\n\nNicely done." } })
apply(826, { "classic", "forever" }, { deDE = { progress = "Ist Zalazane besiegt, {name}?", completion = "Jetzt, da Zalazane beseitigt ist, kann unser Stamm wieder ruhig schlafen.\n\nIch danke Euch, {name}. Der Darkspearstamm schuldet Euch viel. Falls Ihr unter einem Gebrechen leidet, besucht meinen Assistenten Bom'bay, da hinter mir. Sein Voodoo ist stark..." }, enUS = { progress = "Is Zalazane defeated, {name}?", completion = "With Zalazane gone, our tribe can again sleep in peace.\n\nThank you, {name}.  The Darkspear tribe owes you much.  If you suffer from an ailment, visit my assistant Bom'bay, behind me.  His voodoo is strong..." } })
apply(827, { "classic", "forever" }, { deDE = { progress = "Wart Ihr schon in der Knochenhöhle, {name}? Habt Ihr die Senghalsbänder?", completion = "Gut. In diesen Senghalsbändern verbirgt sich das Geheimnis der Burning Blade. Und ich werde dieses Geheimnis lüften..." }, enUS = { progress = "Have you yet entered Skull Rock, {name}?  Do you have the Searing Collars?", completion = "Good.  Hiding within these collars is the secret behind the Burning Blade.  And I will uncover that secret..." } })
apply(828, { "classic", "forever" }, { deDE = { completion = "Willkommen, {name}. Man hat mir Euer Kommen angekündigt und mir von Euren Unternehmungen in Durotar berichtet.\n\nIhr seid ein {class} mit stetig wachsenden Fertigkeiten und Ansehen.\n\nHaltet Euch auf dem reinen Pfad, dann wird Eure Zukunft wahrlich großartig sein." }, enUS = { completion = "Welcome, {name}.  Word reached me of your coming, and of your exploits in Durotar.\n\nYou are a {class} of growing skill and renown.\n\nStay on the pure path, and your future will be great indeed." } })
apply(829, { "classic", "forever" }, { deDE = { progress = "Meine ergebensten Grüße, {class}. Womit kann ich meinem Bruder heute behilflich sein?", completion = "Ah, und wo habt Ihr das her? Der gute Margoz in Klingenhügel hat Euch zu mir geschickt, richtig?\n\nNun, dann lasst mich mal einen Blick darauf werfen..." }, enUS = { progress = "My most humble greetings, {class}.  How might I help my {race} brother today?", completion = "Ah, and where did you get this?  Good Margoz in Razor Hill sent you to me, did he?\n\nWell, let me take a closer look..." } })
apply(830, { "classic", "forever" }, { deDE = { progress = "Ihr seht besorgt aus, {class}. Was habt Ihr da?", completion = "Das sieht gar nicht gut aus. Das war sehr klug von Euch, mir diese Informationen zu bringen." }, enUS = { progress = "There is a look of concern on your face, {class}. What have you there?", completion = "This does not bode well at all. You were wise to bring this information to my attention." } })
apply(831, { "classic", "forever" }, { deDE = { progress = "Seht Ihr nicht, dass ich beschäftigt bin? Ich hoffe, es ist wichtig...", completion = "Unzählige Male habe ich den Kriegshäuptling gedrängt, den Menschen nicht zu trauen, aber persönlicher Stolz steht jetzt hier nicht zur Debatte.\n\nIhr habt der Horde ehrenvoll gedient, {class}.\n\nUnd jetzt entschuldigt mich bitte, ich muss mich über diese Dinge umgehend mit Thrall beraten ..." }, enUS = { progress = "Can you not see that I am busy? This had better be pressing....", completion = "Countless times I urged the Warchief not to trust the humans, but personal pride is not what is at stake here.\n\nYou have served the Horde honorably, young {class}.\n\nNow excuse me, I must counsel Thrall on these matters at once...." } })
apply(832, { "classic", "forever" }, { deDE = { progress = "Ihr habt etwas höchst Wichtiges zu berichten. Das sehe ich an Euren Augen.", completion = "<Untersucht das Auge des brennenden Schattens.>\n\nFaszinierend. Die Stimme, die Ihr hörtet, nannte meinen Namen? Ich bin dafür bekannt, Feinden unseres Kriegshäuptlings nachzustellen, aber... es ist doch seltsam, dass man gerade mich so hervorhebt. Noch seltsamer, dass die Kultisten der Burning Blade, von denen Ihr diesen Anhänger habt, einen Namen wissen, der meinem so ähnlich ist.\n\nIch muss diesen Anhänger studieren. Ich muss ihn studieren und darüber nachdenken, was diese Nachricht bedeuten könnte.\n\nVielen Dank, dass Ihr ihn mir gebracht habt, {name}. Ihr habt unserem Volk einen großen Dienst erwiesen." }, enUS = { progress = "You have something vital to report.  I can sense it behind your eyes.", completion = "<Examines the Eye of Burning Shadow.>\n\nIntriguing.  The voice you heard mentioned my name?  I am known for hunting down enemies of our Warchief, but...it is strange that I was singled out.  Stranger still that the Burning Blade cultists from whom you recovered this pendant have a name so close to my own.\n\nI must study this pendant.  I must study and, and must ponder the meaning of its message.\n\nThank you for bringing this to my attention, {name}.  You have done your people a great service." } })
apply(833, { "classic", "forever" }, { deDE = { progress = "Die Eindringlinge der Borstennacken müssen von unserer heiligen Begräbnisstätte vertrieben werden, {name}.", completion = "Gut gemacht. Ihr habt diesen elenden Borstennacken eine deutliche Warnung erteilt. Sie werden es sich zweimal überlegen, bevor sie erneut versuchen, sich an diesem heiligen Ort einzumischen." }, enUS = { progress = "The Bristleback Interlopers must be driven away from our sacred burial ground, {name}.", completion = "Well done. You have sent those foul Bristlebacks a clear message. They will think twice before attempting to meddle in this holy spot again." } })
apply(834, { "classic", "forever" }, { deDE = { progress = "Ich bin gut, in dem was ich tue, versteht mich jetzt nicht falsch, aber das ist lächerlich! Was soll ich tun, im Sandkasten spielen?", completion = "He, ist das nicht ein Ding? Ihr habt unsere Vorräte zurückgeholt. Is’ ja doll. Jetzt kann ich mich wieder an die Arbeit machen, sobald ich ein paar Leute gefunden habe, die diese Säcke für mich schleppen." }, enUS = { progress = "I'm great at what I do, don't get me wrong, but this is ridiculous! What am I supposed to do, build sand castles?", completion = "Hey, now isn't that just the thing! You've got our supplies back for us. That's great. I'll be able to get back to work just as soon as I can find someone to haul these sacks for me." } })
apply(835, { "classic", "forever" }, { deDE = { progress = "Das traut man einem Typen wie meinem Boss Gazlowe gar nicht zu, aber er scheint immer zu wissen, wie der Hase läuft. \"Keine Angst vor dem großen Schritt\", sagte er.\n\nDie Harpyien werden uns weiterhin belästigen und die Karawanen angreifen, wenn wir nichts unternehmen, oder?", completion = "Ich glaube, ich kann jetzt wieder ruhiger schlafen, da ich weiß, dass die Harpyien unsere Versorgungskarawanen nicht mehr angreifen. Wurde auch langsam Zeit. Wie ich hörte, kommen mit der nächsten Lieferung ein paar nette Spielsachen für mich!\n\nIhr seid ziemlich gut, in dem was Ihr tut, {name}, solltet mal meinen Boss in Ratchet aufsuchen. Ich wette, er hat ein bisschen Arbeit für Euch.\n\nOh, und macht Euch keine Sorgen, ich vergess nicht, Euch für Eure Dienste zu bezahlen." }, enUS = { progress = "You wouldn't think it from a guy like my boss Gazlowe, but he always seemed to know the score. \"Don't be afraid to take that big step,\" he said.\n\nHarpies won't stop bothering us and the caravans won't stop being attacked unless we do something about it, eh?", completion = "I think I can breathe easy now, knowing that the harpies won't be bothering our supply caravans anymore. And not one moment too soon, either. I hear I'm being sent some fun little toys with the next shipment!\n\nYou're pretty good at what you do, {name}, you ought to track down my boss in Ratchet. I'll bet he could find some work for you.\n\nOh, and don't worry, I wouldn't forget to pay you for the service you provided me." } })
apply(836, { "classic", "forever" }, { deDE = { completion = "Ach, IHR habt so heldenhaft OOX-09/HL gerettet! Ich kann Euch gar nicht sagen, wie dankbar ich für Eure Hilfe bin! In meine Serie von Leitrobotern muss noch viel Entwicklungsaufwand gesteckt werden, aber Eure Bergung des Roboters hat mir zahllose Stunden zusätzlicher Schraubarbeit gespart, ganz zu schweigen von dem vielen Gold, das ich spare, weil ich ihn nicht neu bauen muss!\n\nBitte sucht Euch einen von diesen Gegenständen hier aus. Ich danke Euch nochmals für Eure großzügige Hilfe, {name}, meine Roboter und ich stehen in Eurer Schuld!" }, enUS = { completion = "Oh, YOU'RE the great savior of OOX-09/HL!  I cannot even begin to express my thanks for your assistance!  My homing robot series needs more development, but your recovery has saved me countless hours of extra rebuilding time, as well as many gold pieces in manufacture costs!\n\nPlease, take your choice of any of these items I have.  Thank you again for your generous assistance {name}, my robots and I are in your debt!" } })
apply(837, { "classic", "forever" }, { deDE = { progress = "Sie sind zwar einiger Intelligenz und Organisation fähig, doch finde ich es immer wieder erstaunlich, dass die Stacheleber so große Territorien in Kalimdor erobern und halten konnten. Vielleicht sind sie doch gerissenere Feinde als wir ihnen zutrauen...", completion = "Ich werde die Kunde verbreiten, dass die Stacheleber aus ihren Unterschlüpfen vertrieben wurden und dass ihre Gebäude in Brand zu setzen sind. Die Entfernung der Grimmhauer aus Durotar bringt uns dem Ziel näher, die Grenzen unseres neuen Heimatlandes vollständig zu sichern." }, enUS = { progress = "Though they do possess some intelligence and some organization, I find it constantly amazing that the quilboars were able to capture and hold so much territory in Kalimdor. Perhaps they are more crafty an enemy than I give them credit for...", completion = "I will pass along word that the quilboars have been removed from their lairs, and that their structures may be set to fire. The removal of the Razormane from Durotar brings us closer to fully securing the borders of our new homeland." } })
apply(838, { "classic", "forever" }, { deDE = { completion = "Ja, {class}, der Hochexekutor erwähnte, dass Ihr möglicherweise der seid, der mit dem Schlüssel betraut werden kann. Ich habe einen Großteil meiner Studien der Scholomance gewidmet und glaube, dass ich eine Möglichkeit kenne, wie Ihr einen erlangen könnt, der Euch nach Belieben durch die Vordertür bringt.\n\nDiese Aufgabe wird nicht einfach sein, aber das sind solche Aufgaben selten. Ihr seht tatsächlich wie jemand aus, dem das nicht fremd ist." }, enUS = { completion = "Yes, {class}, the High Executor mentioned you might be the one to trust in the matter of the key.  I've dedicated a fair portion of my recent studies to the Scholomance, and I believe I know a means by which you can acquire one that will let you past the front door at will.\n\nThis task will not be easy, but such tasks seldom are.  You most assuredly look like the type to know this as fact." } })
apply(840, { "classic", "forever" }, { deDE = { progress = "Was wollt Ihr, Jungspund? Wenn Ihr nicht wegen einer Anwerbung hier seid, habe ich keine Zeit für Euch.", completion = "Oh, Takrin schickt Euch also? Er ist ein ausgezeichneter Späher und ich weiß nicht, was ich ohne ihn anfangen sollte.\n\nIch unterzeichne Euren Anwerbungsbrief, aber was wir wirklich brauchen, ist jemand in Crossroads." }, enUS = { progress = "What do you want, pup? If you're not here for recruitment, I don't have time for you.", completion = "Oh, so Takrin sent you? He's an excellent scout, I'm not sure what I'd do without him.\n\nI'll sign your recruitment letter, but what we really need is someone at the Crossroads." } })
apply(841, { "classic", "forever" }, { deDE = { progress = "Also, habt Ihr die zehn Wasserbeutel?", completion = "Sehr gut, hier ist eine weitere Kraftquelle. Ich empfehle Euch, sie diesmal weise zu nutzen, falls Ihr nicht erpicht darauf seid, weitere zehn Wasserbeutel für eine weitere Kraftquelle auszugeben." }, enUS = { progress = "Well, have you got the ten water pouches?", completion = "Very well, here is another power source.  I highly recommend you using it properly this time, unless you are eager to spend ten more water pouches for another water source." } })
apply(842, { "classic", "forever" }, { deDE = { progress = "Nanu, nanu, nanu, was haben wir denn hier? Hat Kargal mich nun doch endlich für würdig befunden, mir einen neuen Rekruten zu schicken?", completion = "Na gut, {name}. Ihr wollt also Euren Unterhalt in der Horde verdienen? Hier gibt es eine Menge zu tun, also hört gut zu und tut, was man Euch sagt.\n\nIhr braucht mich gar nicht so ansehen, ich dulde keine Unverschämtheiten. Thrall selbst hat verkündet, dass wir Frauen der Horde Euch Männern gleichgestellt sind. Wenn ihr mir auch nur im geringsten respektlos gegenübertretet, werdet Ihr wahre Schmerzen kennen lernen." }, enUS = { progress = "Well well well, what do we have here? Has Kargal deemed me worthy of another recruit?", completion = "Alright, {name}. You want to earn your keep with the Horde? Well there's plenty to do here, so listen close and do what you're told.\n\n I see that look in your eyes, do not think I will tolerate any insolence. Thrall himself has declared the Hordes females to be on equal footing with you men. Disrespect me in the slightest, and you will know true pain." } })
apply(843, { "classic", "forever" }, { deDE = { progress = "Viele unschuldige Tauren verloren ihr Leben oder wurden zwangsweise aus ihren Vorfahren-Geburtsorten vertrieben, als die Zwerge von Bael Modan kamen. Mein Land muss zurückerobert werden!", completion = "Khazgorm hat das Schicksal ereilt, das er verdient. Ich habe keine Schuldgefühle wegen dieses Narren. Er war ein Ungläubiger in diesem Land.\n\nMöge sein Tod allen als Warnung dienen, die unsere Lebensart zu zerstören trachten.\n\nUnd jetzt gebt mir einen Moment Zeit, damit ich das Tagebuch des Zwergs lesen kann..." }, enUS = { progress = "Many innocent tauren lost their lives or were forced off their ancestral birthplace when the dwarves of Bael Modan arrived. My land must be reclaimed!", completion = "Khazgorm met the fate he earned. I feel no remorse for the fool. He was an infidel on these lands.\n\nMay his death serve as a warning to all those who threaten to disrupt our way of life.\n\nNow let me take a moment to study the dwarf's journal...." } })
apply(844, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Ebenenschreiterschnäbel schon?", completion = "Sehr gut, {name}. Nachdem die Ebenenschreiter jetzt verschwunden sind, ist es für uns einfacher, unsere Nachschubwege intakt zu halten. Und ich hoffe, Ihr habt einige Tricks dort draußen im Brachland gelernt, denn Eure nächste Beute hat etwas mehr Feuer im Blut als die Ebenenschreiter..." }, enUS = { progress = "Have you collected the plainstrider beaks?", completion = "Very good, {name}.  With the plainstriders gone we'll have an easier time keeping our supply chains intact.  And I hope you learned a few tricks out there in the Barrens, for your next prey has a little more fire in its blood than the plainstriders..." } })
apply(845, { "classic", "forever" }, { deDE = { progress = "Wie viele Zhevras habt Ihr schon erschlagen?", completion = "Nicht schlecht, {name}. Diese Zhevras haben sehr viel Kraft in ihren Beinen. Ein gezielter Tritt von ihnen kann sogar einen Tauren von den Hufen hauen!\n\nSieht aus, als würdet auch Ihr über ein bisschen Kraft verfügen. Seid Ihr bereit für eine wahre Herausforderung?" }, enUS = { progress = "How many zhevra have you slain?", completion = "Not bad, {name}.  Those zhevra hold a lot of strength in their legs.  A sharp kick from them can knock even a tauren on its haunches!\n\nIt looks like you have some strength in you too.  Are you ready for a real challenge?" } })
apply(846, { "classic", "forever" }, { deDE = { progress = "Wie ich sehe, seid Ihr zurück, {name}.\n\nKhazgorms Tod mag zwar die Grabungen auf dem Land meiner Vorfahren verzögern, aber der Zerstörung ist damit noch nicht vollständig Einhalt geboten.\n\nDie Burg bei Bael Modan stellt eine ständig wachsende militärische Bedrohung dar. Sie wurde ursprünglich zum Schutz der Grabungsstätte errichtet, ist jetzt aber auch Sitz einer offensiven Streitmacht geworden.\n\nWenn Ihr die Zutaten habt, um die ich gebeten hatte, kann ich eine Ladung herstellen, die diese übereifrigen Zwerge noch einmal über ihre Handlungen hier im Brachland nachdenken lassen wird.", completion = "Wie ich sehe, seid Ihr ziemlich emsig gewesen, {class}.\n\nJetzt werden wir zweifellos bald eine angemessene Überraschung für diese Zwerge parat haben." }, enUS = { progress = "I see you are back, {name}.\n\nWhile Khazgorm's death might delay the digging in my ancestral lands some, it will by no means bring a total end to the destruction.\n\nThe Keep at Bael Modan is an increasing military threat. Built to defend the dig site, it is now poised for offensive force as well.\n\nIf you have the ingredients I requested, I can fashion a charge that will make the hasty dwarves reconsider their actions here in the Barrens.", completion = "I see you are quite industrious, {class}.\n\nNo doubt we shall soon have a fitting surprise for those dwarves." } })
apply(847, { "classic", "forever" }, { deDE = { completion = "Wenn die Verzauberung nachlässt, werde ich mit Gor'mul sprechen. Vielen Dank, dass Ihr geholfen habt, Gor'mul ins Land der Lebenden zurückzuholen. Ich zweifle nicht daran, dass er Euch ebenso dankbar ist." }, enUS = { completion = "When the enchantment wears off, I will speak with Gor'mul. My thanks to you for your help in returning Gor'mul to the land of the living. I have no doubt he thanks you greatly as well." } })
